Consider the feed-forward neural network of width $M$ and depth $L$ given by
\begin{align}
	\mathbf{f}(\mathbf{x}) &= \tfrac{1}{\sqrt{M}}\mathbf{W}_{L+1} \phi(\mathbf{z}_{L}) + \mathbf{b}_{L+1}, \label{eqn:nn-output}\\
	\mathbf{z}_{l} &= \tfrac{1}{\sqrt{M}}\mathbf{W}_{l} \phi(\mathbf{z}_{l - 1}) + \mathbf{b}_{l} \quad \text{for} \quad \text{$l = 2, \ldots, L$}, \label{eqn:nn-recursion}\\
	\mathbf{z}_{1} &= \tfrac{1}{\sqrt{D\ss{i}}}\mathbf{W}_{1} \mathbf{x} + \mathbf{b}_{1}\label{eqn:nn-base}
\end{align}
$(\mathbf{W}_{L+1}, \mathbf{b}_{L+1}) \in \mathbb{R}^{D\ss{o} \times M} \times \mathbb{R}^{D\ss{o}}$,
$(\mathbf{W}_\ell, \mathbf{b}_\ell) \in \mathbb{R}^{M \times M} \times \mathbb{R}^M$ for $\ell = 2, \ldots, L$, and $(\mathbf{W}_1, \mathbf{b}_1) \in \mathbb{R}^{M \times D\ss{i}} \times \mathbb{R}^M$ are the weight and bias parameters, respectively; $\phi\colon \mathbb{R}\to\mathbb{R}$ is the activation function, applied element-wise.

    \label{thm:convergence-of-moments}
	Under the same conditions as \cref{thm:main} (except for the likelihood assumption), there exist universal constants $c_1,c_2,c_3,c_4>0$ such that
    \begin{align*}
    &\norm{\mathbb{E}_Q[\mathbf{f}(\mathbf{x})] - \mathbb{E}_P[\mathbf{f}(\mathbf{x})]}_2
    \\
    &\;\;\; \le c_1c_2^{L-1} \frac{1+ \tfrac{1}{\sqrt{D\ss{i}}} \|\mathbf{x}\|_2}{\sqrt{M}} \operatorname{KL}(Q,P) \parens{\operatorname{KL}(Q,P)^{\frac{L-1}{2}} \!\lor 1}, \\
    &\norm{\mathbb{E}_Q[\mathbf{f}^2(\mathbf{x})] - \mathbb{E}_P[\mathbf{f}^2(\mathbf{x})]}_\infty
    \\
    &\;\;\;  \le c_3c_4^{L-1} \frac{1+ \tfrac{1}{D\ss{i}}\|\mathbf{x}\|_2^2}{\sqrt{M}} \operatorname{KL}(Q,P)^{\tfrac12} \parens{\operatorname{KL}(Q,P)^{L+\tfrac12} \!\lor 1}
    \end{align*}
where $a \lor b=\relax(a,b)$.

In the special case when $L=1$, our bound on the mean has the simpler form



\begin{equation}\label{eqn:1hl-good-constant}
    \!\!\!\norm{\mathbb{E}_Q[\mathbf{f}(\mathbf{x})] \!-\! \mathbb{E}_P[\mathbf{f}(\mathbf{x})]}_2 \!\le\!  \frac{2}{3}\smash{\parens*{\!\frac{1\!+\!\tfrac{1}{D\ss{i}}\|\mathbf{x}\|_2^2}{M}\!}^{\!\!\smash{\frac12}} \!\!\operatorname{KL}(Q,\!P)}.\!\!
\end{equation}

\begin{align}
    \!\!\!\operatorname{KL}(Q^*, P) &\leq \mathbb{E}_{\bm{\uptheta}\sim Q^*}[\log \mathcal{L}(\bm{\uptheta})] -\mathbb{E}_{\bm{\uptheta}\sim P}[\log \mathcal{L}(\bm{\uptheta})]\\
    & \leq \!CN \!-\! \mathbb{E}_{\bm{\uptheta}\sim P}[\textstyle\sum_{n=1}^N \!\log p(\mathbf{y}_n | \mathbf{f}_{\bm{\uptheta}}(\mathbf{x}_n))] \\
    & \leq \! CN \!-\! \mathbb{E}_{\bm{\uptheta} \sim \ensuremath{P}}[\textstyle\sum_{n=1}^N h_n(\mathbf{f}_{\bm{\uptheta}}(\mathbf{x}_n))]
\end{align}

\label{lem:gaussian-kl}
If $P=\mathcal{N}(\mathbf{0},\mathbf{I})$ and $Q = \mathcal{N}(\bm{\upmu}_Q, \mathrm{diag}(\bm{\upsigma}^2_Q))$ It holds that
    \begin{equation}
        \operatorname{KL}(\ensuremath{Q}, \ensuremath{P})
        =
            \tfrac{1}{2}
            (\norm{\bm{\upmu}_Q}_2^2 + \norm{r(\bm{\upsigma}^2_Q)}_1)
    \end{equation}
    where $r\colon (0, \infty) \to [0, \infty)$, $r(a) = a - 1 - \log(a)$ is applied element-wise.

\label{lem:parameter_bound}
   The following inequalities are true:
   \begin{enumerate}
       \item[(i)]
           $\norm{\bm{\upmu}_{\ensuremath{Q}}}^2_2 \le 2 \operatorname{KL}(\ensuremath{Q}, \ensuremath{P})$,
       \item[(ii)]
           $\norm{\bm{\upsigma}_{\ensuremath{Q}} - \mathbf{1}}_2^2 \le 2 \operatorname{KL}(\ensuremath{Q}, \ensuremath{P})$,
       \item[(iii)]
           $\sigma\ss{max}
            \le 1 + \sqrt{2 \operatorname{KL}(\ensuremath{Q}, \ensuremath{P})}
            \le 2 \sqrt{2\operatorname{KL}(\ensuremath{Q}, \ensuremath{P}) \lor 1}$, and
       \item[(iv)]
           $\norm{\bm{\upsigma}_{\ensuremath{Q}}^2 - \mathbf{1}}_2^2
            \le (\sigma\ss{max} + 1)^2 \norm{\bm{\upsigma}_{\ensuremath{Q}} - 1}_2^2
            \le (2 + \sqrt{2 \operatorname{KL}(\ensuremath{Q}, \ensuremath{P})})^2 (2 \operatorname{KL}(\ensuremath{Q}, \ensuremath{P}))$.
   \end{enumerate}

\label{prop:optimised_param_bound}
   Let $\mathbf{W}$ be an arbitrary weight matrix and let $\mathbf{b}$ be an arbitrary bias vector.
   Then
   \begin{equation}
       \norm{\mathbb{V}\ss{d}[\operatorname{vec}(\mathbf{W})]}_\infty
       + \norm{\mathbb{V}\ss{d}[\mathbf{b}]}_\infty
       + \norm{\mathbb{E}[\mathbf{b}^2]}_\infty
       \le (\sqrt{2} + \sqrt{2\operatorname{KL}(Q, P)})^2.
   \end{equation}

\label{thm:app-convergence-of-mean}
   Let $Q$ be a mean-field variational posterior and $P=\mathcal{N}(\mathbf{0},\mathbf{I})$ denote the prior over a neural network with $L$ hidden layers and $M$ neurons per hidden layer.
   Suppose $\phi\ss{e}=\alpha$ for some $\alpha \in \mathbb{R}$ and $\phi\colon \mathbb{R} \to \mathbb{R}$ is $1$-Lipschitz.
   Let $\mathbf{x} \in \mathbb{R}^{D\ss{i}}$ and let $\widetilde{\mathbf{f}}_{\theta}(\mathbf{x}) = \mathbf{f}_\theta(\mathbf{x}) - \tfrac\alpha{\sqrt{M}}\mathbf{W}_{L+1}\mathbf{1} - \mathbf{b}_{L+1}$ denote the network output excluding final bias and even part of the final activation.
   Then there exist universal constants $c_1 \leq 4$ and $c_2 \leq 6$ such that 
   \begin{equation}
        \norm{\mathbb{E}_Q[\widetilde{\mathbf{f}}_{\theta}(\mathbf{x})]}_2
       \le c_1c_2^{L-1} L \frac{\abs{\alpha} + 1+ \|\mathbf{x}\|_2/\sqrt{D\ss{i}}}{\sqrt{M}} \operatorname{KL}(Q, P) \parens{(2\operatorname{KL}(\ensuremath{Q}, \ensuremath{P}))^\frac{L-1}{2} \lor 1}.
   \end{equation}

\label{cor:difference-of-means}
    With the same notation and assumptions as in \cref{thm:app-convergence-of-mean}, for $\mathbf{x}, \mathbf{x}' \in \mathbb{R}^{D\ss{i}}$ we have 
    \begin{align}
        \norm{\mathbb{E}_Q[\mathbf{f}_{\theta}(\mathbf{x})] -\mathbb{E}_Q[\mathbf{f}_{\theta}(\mathbf{x}')]}_2 \leq c_1c_2^{L-1} L \frac{2\abs{\alpha} + 2+( \|\mathbf{x}\|_2+\|\mathbf{x}'\|_2)/\sqrt{D\ss{i}}}{\sqrt{M}} \operatorname{KL}(Q, P) \parens{(2\operatorname{KL}(\ensuremath{Q}, \ensuremath{P}))^\frac{L-1}{2} \lor 1}
    \end{align}

\label{lem:last-layer-bound}
 Suppose $\ensuremath{Q}$ is mean-field Gaussian, $\ensuremath{P}=\mathcal{N}(\mathbf{0}, \mathbf{I})$, $\phi_{e}=\alpha$, with $\alpha \in \mathbb{R}$ and $\phi$ is $1$-Lipschitz. Then,
\begin{align}
    \norm{\mathbb{E}[\phi\ss{o}(\mathbf{z}_L(\mathbf{x}))]}_2
    &\le 2L(2 + \abs{\alpha} + \tfrac{1}{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{L - 1}\sqrt{2\operatorname{KL}(Q,P)}(\sqrt{2\operatorname{KL}(Q,P)} \lor 1)^{L - 1},
\end{align}
where $c>0$ is a universal constant.

Let every expectation be under $\ensuremath{Q}$. Define $K=\sqrt{2\operatorname{KL}(Q,P)}$. By a slight abuse of notation, let $\mathbf{z}_L = \mathbf{z}_L(\mathbf{x})$.

To begin with, note that
\begin{align}
    \norm{\mathbb{E}[\widetilde{\mathbf{f}}_{\theta}(\mathbf{x})]}_2 
    &= \tfrac1{\sqrt{M}} \norm{\mathbb{E}[\mathbf{W}_{L+1}]\mathbb{E}[(\phi\ss{o}(\mathbf{z}_L)]}_2.



\end{align}
Using \cref{lem:parameter_bound}, $\norm{\mathbb{E}[\mathbf{W}_{L+1}]}\ss{F} \le K$. We then apply \cref{lem:last-layer-bound},
\begin{align}
    \norm{\mathbb{E}[\widetilde{\mathbf{f}}_{\theta}(\mathbf{x})]}_2 
    &\le \frac{K}{\sqrt{M}} 
        2L\parens*{2 + \abs{\alpha}+\frac{1}{\sqrt{D\ss{i}}}\|\mathbf{x}\|_2}(2 + 2c)^{L - 1} K(K \lor 1)^{L - 1} \\

    &= \frac{2L}{\sqrt{M}} \parens*{2 + \abs{\alpha}+\frac{1}{\sqrt{D\ss{i}}}\|\mathbf{x}\|_2} (2 + 2c)^{L-1}\operatorname{KL}(\ensuremath{Q}, \ensuremath{P})\parens{(2\operatorname{KL}(\ensuremath{Q}, \ensuremath{P}))^\frac{L-1}{2} \lor 1}.
\end{align}

\label{lem:contraction}
   Let $\phi_1,\phi_2\colon \mathbb{R} \to \mathbb{R}$ be $1$-Lipschitz and odd.
   Let the triple $(\mathbf{W}, \mathbf{z}, \mathbf{b})$ be  (possibly dependent) random variables such that
   \begin{equation}
       (\mathbf{W} - \mathbb{E}[\mathbf{W}], \mathbf{z}, \mathbf{b} - \mathbb{E}[\mathbf{b}])
       \overset{\text{d}}{=}
       (-(\mathbf{W} - \mathbb{E}[\mathbf{W}]), \mathbf{z}, -(\mathbf{b} - \mathbb{E}[\mathbf{b}]))
   \end{equation}
   Then
   \begin{align}
       &\norm{\mathbb{E}[\phi_1(\mathbf{W} \phi_2(\mathbf{z}) + \mathbf{b})]}_2 
   \le \norm{\mathbb{E}[\mathbf{W}]}\ss{F}\mathbb{E}[\norm{\mathbf{z}}_2] + \mathbb{E}[\norm{\mathbf{W} - \mathbb{E}[\mathbf{W}]}_2] \norm{\mathbb{E}[\mathbf{z}]}_2 + \norm{\mathbb{E}[\mathbf{b}]}_2
   \end{align}

\label{lem:expectation_bound}
   Let $\mathbf{A} \in \mathbb{R}^{I \times J}$ be a zero-mean random matrix with independent Gaussian entries with variances bounded by $\sigma^2$.
   Then
   \begin{equation}
       \mathbb{E}[\norm{\mathbf{A}}_2] \le 2 \sigma \sqrt{I \lor J}.
   \end{equation}
   Moreover, if the variances of the entries of $\mathbf{A}$ are all equal to one, then
   \begin{equation}
       \mathbb{P}(\norm{\mathbf{A}}_2 \ge 2 \sqrt{I \lor J} + \delta) \le 2 \exp(-\tfrac1{2} \delta^2).
   \end{equation}

We slightly generalise Exercise 5.14 from \citet{Wainwright:2019:High-Dimensional_Statistics_A_Non-Asymptotic_Viewpoint}.
To begin with, rewrite the operator norm as
\begin{equation}
    \norm{\mathbf{A}}_2
    = \relax_{(\mathbf{u}, \mathbf{v}) \in \mathbb{S}^{I - 1} \times \mathbb{S}^{J - 1}} \lra{\mathbf{u}, \mathbf{A} \mathbf{v}}.
\end{equation}
Define the zero-mean Gaussian process $Z_{\mathbf{u}, \mathbf{v}} = \lra{\mathbf{u}, \mathbf{A} \mathbf{v}}$ indexed on $\mathbb{S}^{I - 1} \times \mathbb{S}^{J - 1}$ and
define $\mathbf{S}$ by $S_{i,j} = \mathbb{V}[A_{i,j}] \le \sigma^2$.
Note that, by independence of the entries of $\mathbf{A}$,
\begin{align}
    \mathbb{E}[(Z_{\mathbf{u},\mathbf{v}} - Z_{\mathbf{w}, \mathbf{x}})^2]
    &= \mathbb{E}[Z^2_{\mathbf{u}, \mathbf{v}} - 2 Z_{\mathbf{u},\mathbf{v}} Z_{\mathbf{w}, \mathbf{x}} + Z^2_{\mathbf{w}, \mathbf{x}}] \\
    &= \textstyle
        \sum_{i=1,j=1}^{I,J} S_{ij} u_i^2 v_j^2
        - 2 \sum_{i=1,j=1}^{I,J} S_{ij} u_i v_j w_i x_j
        + \sum_{i=1,j=1}^{I,J} S_{ij} w_i^2 x_j^2 \\
    &= \textstyle
        \sum_{i=1,j=1}^{I,J} S_{ij} (u_i v_j - w_i x_j)^2 \\
    &\le \textstyle
        \sigma^2 \sum_{i=1,j=1}^{I,J} (u_i v_j - w_i x_j)^2 \\
    &=
        \sigma^2 \norm{\mathbf{u} \mathbf{v}^{\text{\textsf{T}}} - \mathbf{w} \mathbf{x}^{\text{\textsf{T}}}}\ss{F}^2.
\end{align}
Also consider the zero-mean Gaussian process $Y_{\mathbf{u}, \mathbf{v}} = \sigma \lra{\mathbf{u}, \bm{\upvarepsilon}_1} + \sigma  \lra{\mathbf{v}, \bm{\upvarepsilon}_2}$ again indexed on $\mathbb{S}^{I - 1} \times \mathbb{S}^{J - 1}$, where $\bm{\upvarepsilon}_1 \in \mathbb{R}^I$ and $\bm{\upvarepsilon}_2 \in \mathbb{R}^J$ are standard Gaussian vectors.
Then
\begin{align}
    \mathbb{E}[(Y_{\mathbf{u}, \mathbf{v}} - Y_{\mathbf{w}, \mathbf{x}})^2]
    &= \sigma^2 \mathbb{E}[(\lra{\mathbf{u} - \mathbf{w}, \bm{\upvarepsilon}_1} +  \lra{\mathbf{v} - \mathbf{x}, \bm{\upvarepsilon}_2})^2] \\
    &= \sigma^2 \mathbb{E}[\lra{\mathbf{u} - \mathbf{w}, \bm{\upvarepsilon}_1}^2 + \lra{\mathbf{v} - \mathbf{x}, \bm{\upvarepsilon}_2}^2] \\
    &= \sigma^2 (\norm{\mathbf{u} - \mathbf{w}}_2^2 + \norm{\mathbf{v} - \mathbf{x}}_2^2).
\end{align}
Using that $\norm{\mathbf{u}}_2 = \norm{\mathbf{v}}_2 =\norm{\mathbf{x}}_2 =\norm{\mathbf{w}}_2 = 1$, careful algebra \citep[see, e.g., page 164 from][]{Wainwright:2019:High-Dimensional_Statistics_A_Non-Asymptotic_Viewpoint} shows that $\norm{\mathbf{u} \mathbf{v}^{\text{\textsf{T}}} - \mathbf{w} \mathbf{x}^{\text{\textsf{T}}}}\ss{F}^2 \le \norm{\mathbf{u} - \mathbf{w}}_2^2 + \norm{\mathbf{v} - \mathbf{x}}_2^2$:
\begin{align}
    (u_i v_j - w_i x_j)^2
    &= (u_i v_j - w_i v_j + w_i v_j - w_i x_j)^2 \\
    &= (u_i - w_i)^2 v_j^2 + w_i^2 (v_j - x_j)^2
        + 2 (u_i v_j - w_i v_j) (w_i v_j - w_i x_j) \\
    &= (u_i - w_i)^2 v_j^2 + w_i^2 (v_j - x_j)^2
        + 2 (u_i w_i - w_i^2) (v^2_j - v_j x_j).
\end{align}
Therefore, summing over $i \in [I]$ and $j \in [J]$ and using that $\norm{\mathbf{v}}_2 = \norm{\mathbf{w}}_2 = 1$,
\begin{equation}
    \norm{\mathbf{u} \mathbf{v}^{\text{\textsf{T}}} - \mathbf{w} \mathbf{x}^{\text{\textsf{T}}}}^2\ss{F}
    = \norm{\mathbf{u} - \mathbf{w}}_2^2 + \norm{\mathbf{v} - \mathbf{x}}_2^2 + 2(\lra{\mathbf{u}, \mathbf{w}} - 1)(1 - \lra{\mathbf{v}, \mathbf{x}})
    \le \norm{\mathbf{u} - \mathbf{w}}_2^2 + \norm{\mathbf{v} - \mathbf{x}}_2^2
\end{equation}
where the inequality follows from additionally using that $\norm{\mathbf{u}}_2 = \norm{\mathbf{x}}_2 = 1$.
Using this result, we find
\begin{equation}
    \mathbb{E}[(Z_{\mathbf{u},\mathbf{v}} - Z_{\mathbf{w}, \mathbf{x}})^2] \le \mathbb{E}[(Y_{\mathbf{u}, \mathbf{v}} - Y_{\mathbf{w}, \mathbf{x}})^2].
\end{equation}
Hence, denoting
$Z^* = \relax_{(\mathbf{u}, \mathbf{v}) \in \mathbb{S}^{I - 1} \times \mathbb{S}^{J - 1}} Z_{\mathbf{u},\mathbf{v}}$
and $Y^* = \relax_{(\mathbf{u}, \mathbf{v}) \in \mathbb{S}^{I - 1} \times \mathbb{S}^{J - 1}} Y_{\mathbf{u},\mathbf{v}}$, by the Sudakov--Fernique comparison theorem \citep[Theorem 5.27,][]{Wainwright:2019:High-Dimensional_Statistics_A_Non-Asymptotic_Viewpoint},
we conclude that
\begin{equation}
    \mathbb{E}[\norm{\mathbf{A}}_2] = \mathbb{E}[Z^*]
    \le \mathbb{E}[Y^*]
    \overset{\smash{\text{(i)}}}{=} \sigma\,\mathbb{E}[\norm{\bm{\upvarepsilon}_1}_2 + \norm{\bm{\upvarepsilon}_2}_2]
    \overset{\smash{\text{(ii)}}}{\le} \sigma(\sqrt{I} + \sqrt{J})
\end{equation}
where (i) follows from that the suprema are achieved by $\bm{\upvarepsilon}_1/\norm{\bm{\upvarepsilon}_1}_2$ and $\bm{\upvarepsilon}_2/\norm{\bm{\upvarepsilon}_2}_2$ for $\mathbf{u}$ and $\mathbf{v}$, respectively, and  (ii) follows from Jensen's inequality applied to the square root. 

For the second statement, assume that all entries of $\mathbf{A}$ have variance one, so $\sigma^2=1$.
We apply concentration of Gaussian suprema \citep[e.g., Exercise 5.10 by][]{Wainwright:2019:High-Dimensional_Statistics_A_Non-Asymptotic_Viewpoint} to $Z_{\mathbf{u},\mathbf{v}}$:
\begin{equation}
    \mathbb{P}(
        \abs{
            Z^* - \mathbb{E}[Z^*]
        } \ge \delta
    ) \le 2 \exp(-\tfrac1{2 v} \delta^2)
\end{equation}
where
\begin{equation}
    v = \relax_{(\mathbf{u}, \mathbf{v}) \in \mathbb{S}^{I - 1} \times \mathbb{S}^{J - 1}} \mathbb{V}[Z_{\mathbf{u},\mathbf{v}}] = \relax_{(\mathbf{u}, \mathbf{v}) \in \mathbb{S}^{I - 1} \times \mathbb{S}^{J - 1}}\norm{\mathbf{u}}_2^2 \norm{\mathbf{v}}_2^2 = 1.
\end{equation}
Therefore, using the bound on $\mathbb{E}[Z^*]$ from the first statement,
\begin{equation}
    \mathbb{P}(\norm{\mathbf{A}}_2 \ge 2 \sqrt{I \lor J} + \delta) \le 2 \exp(-\tfrac1{2} \delta^2),
\end{equation}
which concludes the proof.

\label{lem:bound}
   Let $\phi_1, \phi_2 \colon \mathbb{R} \to \mathbb{R}$ be $1$-Lipschitz and odd, and let $\alpha \in \mathbb{R}$.
   Let $(\mathbf{W}, \mathbf{z}, \mathbf{b})$ be independent random variables with $\mathbf{W}$ and $\mathbf{b}$, not $\mathbf{z}$, symmetric around their means.
   Moreover, assume that $\mathbf{W}$ has independent sub-Gaussian entries with sub-Gaussian parameters bounded by $\sigma$.
   Then there exists a universal constant $c > 0$ such that
   \begin{align}
       &\norm{\mathbb{E}[\phi_1(\tfrac1{\sqrt{M}}\mathbf{W} (\phi_2 + \alpha)(\mathbf{z}) + \mathbf{b})]}_2 \nonumber \\
       &\qquad\le \parens{\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}}_2] + \abs{\alpha}}\norm{\mathbb{E}[\mathbf{W}]}\ss{F} + c \sigma \norm{\mathbb{E}[\mathbf{z}]}_2 + \norm{\mathbb{E}[\mathbf{b}]}_2.
   \end{align}
   with $c$ the same constant as in \cref{lem:expectation_bound}.

By \cref{lem:expectation_bound}, there exists a universal constant $c > 0$ such that
\begin{equation}
    \mathbb{E}[\norm{\mathbf{W} - \mathbb{E}[\mathbf{W}]}_2] \le c \sigma \sqrt{M}
    \implies
    \mathbb{E}[\norm{\tfrac{1}{\sqrt{M}}\mathbf{W} - \mathbb{E}[\tfrac{1}{\sqrt{M}}\mathbf{W}]}_2] 
    \le c \sigma.
\end{equation}
The result then follows from \cref{rem:symmetry_offset} with $\tfrac{1}{\sqrt{M}}\mathbf{W}$ instead of $\mathbf{W}$.

\label{lem:bound_norm}
   Assume the conditions of \cref{lem:bound}.
   Then 
   \begin{align}
       &\mathbb{E}[\norm{\tfrac1{\sqrt{M}}\mathbf{W} (\phi_2 + \alpha)(\mathbf{z}) + \mathbf{b}}_2] \nonumber \\
       &\qquad\le (\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}}_2] + \abs{\alpha}) (\norm{\mathbb{E}[\mathbf{W}]}_2 + c\sigma \sqrt{M})  + \norm{\mathbb{E}[\mathbf{b}]}_2+ c \sigma \sqrt{M}.
   \end{align}

Use the triangle inequality and recall that $\norm{\phi_2(\mathbf{z})}_2 \le \norm{\mathbf{z}}_2$ (proof of \cref{lem:lipschitz}):
\begin{align}
    &\mathbb{E}[\norm{\tfrac1{\sqrt{M}}\mathbf{W} \phi_2(\mathbf{z}) + \tfrac{\alpha}{\sqrt{M}}\mathbf{W} \mathbf{1} + \mathbf{b}}_2] \nonumber \\
    &\qquad\le
        (\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}}_2] + \abs{\alpha}) \mathbb{E}[\norm{\mathbf{W}}_2]  + \mathbb{E}[\norm{\mathbf{b}}_2]\\
    &\qquad\le
        (\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}}_2] + \abs{\alpha}) (\norm{\mathbb{E}[\mathbf{W}]}_2 + c\sigma \sqrt{M})  + \norm{\mathbb{E}[\mathbf{b}]}_2 + c \sigma \sqrt{M}
\end{align}
where in the second inequality we use the triangle inequality in combination with \cref{lem:expectation_bound}.

\label{prop:recursion}
    Let $a, b\in \mathbb{R}$ and $\{c_\ell\}_{\ell=1}^L$, with $c_\ell \in \mathbb{R}$. Suppose, $c_\ell \le a c_{\ell-1} + b$ with $a, b \ge 0$ for $h > 1$.
    Then for $2 \leq \ell \leq L$
    \begin{equation}
        c_\ell \le a^{\ell - 1} c_1 + (1 + a)^{\ell - 2} b.
    \end{equation}

    The proof is a standard induction. In the base case $h=2$, we have to prove,
    \begin{align}
        c_2 \leq a c_1 + b,
    \end{align}
which holds because this is simply our assumption on the $c_\ell$ with $\ell=2$. For the inductive step, we now assume that $c_\ell \leq a^{\ell - 1} c_1 + (1 + a)^{\ell - 2} b$. Under this assumption, we have,
\begin{align}
    c_{\ell+1} &\leq  a c_{\ell} + b 
     \leq a^{\ell} c_1 + a(1 + a)^{\ell - 2} b + b 
     = a^{\ell} c_1 + (1 + a)^{\ell - 1} b.
\end{align}

\begin{align}
    c_{\ell+1} &\leq  a c_{\ell} + b 
     \leq a^{\ell} c_1 + a(1 + a)^{\ell - 2} b + b 
     = a^{\ell} c_1 + (1 + a)^{\ell - 1} b.
\end{align}

\label{lem:expected-norm-bound}
Define $K = \sqrt{2\operatorname{KL}(\ensuremath{Q},\ensuremath{P})}$. Then for $1 \le \ell \leq L$
\begin{align}
     \tfrac1{\sqrt{M}}\mathbb{E}_Q[\norm{\mathbf{z}_\ell}_2] &\le (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^\ell(K \lor 1)^\ell,
\end{align}
where $c$ is the same absolute constant from \cref{lem:contraction}.

\label{lem:norm-expecation}
    Define $K = \sqrt{2\operatorname{KL}(\ensuremath{Q},\ensuremath{P})}$. Then for $1 \le \ell \leq L$
\begin{align}
     \norm{\mathbb{E}_Q[\mathbf{z}_\ell]}_2 &\le 2\ell (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{\ell-1}K(K \lor 1)^{\ell-1},
\end{align}
where $c$ is the same absolute constant from \cref{lem:contraction}

The proof proceeds by induction on $\ell$.
\paragraph{Base Case}
For the first layer, $\ell = 1$, by linearity of expectation, triangle inequality and the definition of the spectral norm,
\begin{equation}
    \norm{\mathbb{E}[\mathbf{z}_1]}_2 \le \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbb{E}[\mathbf{W}_1]}\ss{2} \norm{\mathbf{x}}_2 + \norm{\mathbb{E}[\mathbf{b}_1]}_2 \le \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbb{E}[\mathbf{W}_1]}\ss{F} \norm{\mathbf{x}}_2 + \norm{\mathbb{E}[\mathbf{b}_1]}_2.
\end{equation}
We then apply
\cref{lem:parameter_bound} (i.), to conclude $\norm{\mathbb{E}[\mathbf{W}_1]},\norm{\mathbb{E}[\mathbf{b}_1]}_2 \leq K$,
\begin{equation}
    \norm{\mathbb{E}[\mathbf{z}_1]}_2 \le (1+ \tfrac{1}{\sqrt{D\ss{i}}}\|\mathbf{x}\|_2)K \leq 2(2+|\alpha|+\tfrac{1}{\sqrt{D\ss{i}}}\|\mathbf{x}\|_2)K .
\end{equation}
\paragraph{Inductive step}
We take the inductive hypothesis, \begin{align}
    \norm{\mathbb{E}_Q[\mathbf{z}_\ell]}_2 &\le 2\ell (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{\ell-1}K(K \lor 1)^{\ell-1}.
\end{align}
By an application of \cref{lem:bound}, 
\begin{equation}
    \norm{\mathbb{E}[\mathbf{z}_{\ell+1}]}_2 \le (\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}_{\ell}}_2] + \abs{\alpha})\norm{\mathbb{E}[\mathbf{W}_{\ell+1}]}\ss{F} + c \sigma\ss{max} \norm{\mathbb{E}[\mathbf{z}_{\ell}]}_2 + \norm{\mathbb{E}[\mathbf{b}_{\ell+1}]}_2
\end{equation}
Applying
\cref{lem:parameter_bound} (i., iii.), 
\begin{equation}
   \norm{\mathbb{E}[\mathbf{z}_{\ell+1}]}_2 \le (\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}_{\ell}}_2] + \abs{\alpha} + 1)K + 2c (K\lor 1) \norm{\mathbb{E}[\mathbf{z}_{\ell}]}_2 
\end{equation}
Using the inductive hypothesis, 
\begin{align}
    2c(K \lor 1)\norm{\mathbb{E}_Q[\mathbf{z}_\ell]}_2] &\le 4c\ell (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{\ell-1}K(K \lor 1)^{\ell} \\
    & \le 2\ell (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{\ell}K(K \lor 1)^{\ell}.
\end{align}
We then make use of \cref{lem:expected-norm-bound},
\begin{align}
  K(1 + |\alpha| + \tfrac1{\sqrt{M}}\mathbb{E}_Q[\norm{\mathbf{z}_\ell}_2]) &\le K\left(1 + |\alpha| + (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^\ell(K \lor 1)^\ell\right) \\
  & \le  2(2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^\ell K(K \lor 1)^\ell
\end{align}
Hence,
\begin{equation*}
   \norm{\mathbb{E}[\mathbf{z}_{\ell+1}]}_2 \le (2\ell+2)(2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^\ell K(K \lor 1)^\ell. \qedhere
\end{equation*}

The proof is essentially identical to the inductive step in \cref{lem:norm-expecation}. 

To begin with, we apply \cref{lem:bound} to the deep architecture.
For the last hidden layer,
\begin{equation}
    \norm{\mathbb{E}[\phi\ss{o}(\mathbf{z}_L)]}_2 \le (\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}_{L-1}}_2] + \abs{\alpha})\norm{\mathbb{E}[\mathbf{W}_L]}\ss{F} + c \sigma\ss{max} \norm{\mathbb{E}[\mathbf{z}_{L - 1}]}_2 + \norm{\mathbb{E}[\mathbf{b}_{L}]}_2.
\end{equation}
We apply \cref{lem:parameter_bound} (i., iii.), yielding,
\begin{equation}
    \norm{\mathbb{E}[\phi\ss{o}(\mathbf{z}_L)]}_2 \le (\tfrac1{\sqrt{M}}\mathbb{E}[\norm{\mathbf{z}_{L-1}}_2] + \abs{\alpha})K+ 2c (K\lor 1) \norm{\mathbb{E}[\mathbf{z}_{L - 1}]}_2 + K. \label{eqn:bound-w-preactivations}
\end{equation}

We then make use of \cref{lem:expected-norm-bound},
\begin{align}
  K(1 + |\alpha| + \tfrac1{\sqrt{M}}\mathbb{E}_Q[\norm{\mathbf{z}_{L-1}}_2]) &\le K\left(1 + |\alpha| + (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{L-1}(K \lor 1)^{L-1}\right) \\
  & \le  2(2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{L-1} K(K \lor 1)^{L-1}. \label{eqn:bound-norm}
\end{align}
From \cref{lem:norm-expecation},
\begin{align}
    2c(K \lor 1)\norm{\mathbb{E}_Q[\mathbf{z}_{L-1}]}_2] &\le 4c(L-1) (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{L-2}K(K \lor 1)^{L-1} \\
    & \le 2(L-1) (2 + \abs{\alpha} + \tfrac1{\sqrt{D\ss{i}}}\norm{\mathbf{x}}_2)(2 + 2c)^{L-1}K(K \lor 1)^{L-1}. \label{eqn:bound-exp}
\end{align}
Combining \cref{eqn:bound-w-preactivations,eqn:bound-norm,eqn:bound-exp} gives the result. \qedhere

\label{thm:app-convergence-of-variance}
    Let $Q$ be a mean-field variational posterior and $P=\mathcal{N}(\mathbf{0},\mathbf{I})$ denote the prior over a neural network with $L$ hidden layers and $M$ neurons per hidden layer.
    Suppose $\phi\ss{e}=\alpha$ for some $\alpha \in \mathbb{R}$ and $\phi\colon \mathbb{R} \to \mathbb{R}$ is $1$-Lipschitz.
    Let $\mathbf{x} \in \mathbb{R}^{D\ss{i}}$ and let $\widetilde{\mathbf{f}}_{\theta}(\mathbf{x}) = \mathbf{f}_\theta(\mathbf{x}) - \tfrac\alpha{\sqrt{M}}\mathbf{W}_{L+1}\mathbf{1} - \mathbf{b}_{L+1}$ denote the network output excluding final bias and even part of the final activation. Then 
    \begin{equation}
        \norm{\mathbb{E}_Q[\tilde{\mathbf{f}}_{\bm{\uptheta}}^2(\mathbf{x})] - \mathbb{E}_P[\tilde{\mathbf{f}}_{\bm{\uptheta}}^2(\mathbf{x})]}_\infty
        \le
            c_1L^{1/2} \rho_{\alpha, M}^L
            \frac
                {\alpha^2 + 1 + \tfrac1{D\ss{i}}\norm{\mathbf{x}}_2^2}
                {\sqrt{M}}  
            \sqrt{\operatorname{KL}(\ensuremath{Q}, \ensuremath{P})} (2\operatorname{KL}(\ensuremath{Q}, \ensuremath{P}) \lor 1)^{L+\tfrac12},
    \end{equation}
    where $c_1 = 16 + 25\sqrt{2} \in (51, 52)$ and where $\rho_{\alpha, M} \in (17, 97)$ is defined in \cref{lem:diag-frob-norm}.

\label{lem:app-diagonal-variance}
Define $\mathbf{\Sigma}_{Q} =\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}\mathbf{w}_{L+1}^{\text{\textsf{T}}}] -  \mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]^{\text{\textsf{T}}}$, which is a diagonal matrix with the variances of $\mathbf{w}_{L+1}$ as entries. Let 
\begin{align}
    D^i_{\ensuremath{P}}(\mathbf{x}) &= \tfrac{1}{M}\operatorname{tr}(\mathbb{E}_{\ensuremath{P}}[\mathbf{w}_{L+1}\mathbf{w}_{L+1}^{\text{\textsf{T}}}]\mathbb{E}_{\ensuremath{P}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}])\\
        D^i_{\ensuremath{Q}}(\mathbf{x}) &=\tfrac{1}{M}\operatorname{tr}(\mathbf{\Sigma}_{Q}\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}])
\end{align}
Then,
\begin{align}
    |D^{i}_{\ensuremath{Q}}(\mathbf{x}) - D^{i}_{\ensuremath{P}}(\mathbf{x})| 
    &\leq  
    \left(16 + \sqrt{2}\right) L^{1/2}
    \rho_{\alpha, M}^{L}\frac{\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2}{\sqrt{M}}  \sqrt{\operatorname{KL}(\ensuremath{Q},\ensuremath{P})} (2 \operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \lor 1)^{L+\tfrac12}
\end{align}
where $\rho_{\alpha, M} \in (17, 97)$ is defined in \cref{lem:diag-frob-norm}.

\label{lem:app-off-diagonal-variance}
Define $
O^i_{\ensuremath{Q}}(\mathbf{x}) = \frac{1}{M}\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]^{\text{\textsf{T}}}\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]$.
Then,



\begin{equation}
    |O^i_{\ensuremath{Q}}(\mathbf{x})| \leq 48\gamma_\alpha^{L}\frac{\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2}{\sqrt{M}}
    \operatorname{KL}(\ensuremath{Q},\ensuremath{P})(2\operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \lor 1)^{L},
\end{equation}
where $\gamma_\alpha = 9 + \sqrt{83} \in (18,19)$ if $\alpha=0$ and $\gamma_\alpha = 55$ if $\alpha\neq0$.

\label{lem:expectation_squared_bound_update}
   Let $\mathbf{A} \in \mathbb{R}^{I \times J}$ have independent standard Gaussian entries.
   Then
   \begin{equation}
       \mathbb{E}[\norm{\mathbf{A}}^2_2]
       \le \eta_{I \lor J} (I \lor J),
   \end{equation}
   where $\eta_{I \lor J}$ takes the value $\tfrac19(37+6\sqrt{2\pi}) \in (5,6)$ if $I\lor J\ge 36$ and $4(2+\sqrt{2\pi}) \in (18,19)$ otherwise.

    We integrate the tail bound from \cref{lem:expectation_bound}:
    \begin{equation}
        \mathbb{P}(\norm{\mathbf{A}}_2 \ge 2 \sqrt{I \lor J} + \delta) \le 2 \exp(-\tfrac1{2} \delta^2).
    \end{equation}
     To integrate the tail bound, use the layer cake trick:
    \begin{align}
        \mathbb{E}[\norm{\mathbf{A}}^2_2]
        &= \int_0^\infty \ensuremath{P}(\norm{\mathbf{A}}^2_2 > u) \isd u \\
        &\le 4(I \lor J) + \int_0^\infty \ensuremath{P}(\norm{\mathbf{A}}^2_2 > 4(I \lor J) + u) \isd u.
    \end{align}
    Consider the change of variables defined by
    \begin{equation}
        4(I \lor J) + u = (2 \sqrt{I \lor J} + v)^2.
    \end{equation}
    Then
    $\sd u = 2( 2\sqrt{I \lor J} + v) \isd v$,
    so
    \begin{align}
        \mathbb{E}[\norm{\mathbf{A}}^2_2]
        &\le
            4(I \lor J)
            + 2\int_0^\infty \ensuremath{P}(\norm{\mathbf{A}}_2 > 2 \sqrt{I \lor J} + v) (2 \sqrt{I \lor J} + v) \isd v \\
        &\le\vphantom{\int_0^\infty}
            4(I \lor J)
            + 4\int_0^\infty e^{-\tfrac12 v^2} (2 \sqrt{I \lor J} + v) \isd v \\
        &=\vphantom{\int_0^\infty}
            4(I \lor J)
            + 4 \sqrt{2\pi} \sqrt{I \lor J} + 4.
    \end{align}
The claimed bound then follows by checking cases.

\begin{align}
        \mathbb{E}[\norm{\mathbf{A}}^2_2]
        &= \int_0^\infty \ensuremath{P}(\norm{\mathbf{A}}^2_2 > u) \isd u \\
        &\le 4(I \lor J) + \int_0^\infty \ensuremath{P}(\norm{\mathbf{A}}^2_2 > 4(I \lor J) + u) \isd u.
    \end{align}

\begin{align}
        \mathbb{E}[\norm{\mathbf{A}}^2_2]
        &\le
            4(I \lor J)
            + 2\int_0^\infty \ensuremath{P}(\norm{\mathbf{A}}_2 > 2 \sqrt{I \lor J} + v) (2 \sqrt{I \lor J} + v) \isd v \\
        &\le\vphantom{\int_0^\infty}
            4(I \lor J)
            + 4\int_0^\infty e^{-\tfrac12 v^2} (2 \sqrt{I \lor J} + v) \isd v \\
        &=\vphantom{\int_0^\infty}
            4(I \lor J)
            + 4 \sqrt{2\pi} \sqrt{I \lor J} + 4.
    \end{align}

\label{lem:outer}
   Let $\phi_1,\phi_2\colon\mathbb{R} \to \mathbb{R}$ be $1$-Lipschitz and odd.
   Let the triple $(\mathbf{W}, \mathbf{z}_2, \mathbf{b}) \in \mathbb{R}^{M_1\times M_2} \times \mathbb{R}^{M_2} \times \mathbb{R}^{M_1}$ be (possibly dependent) random variables such that, for all Rademacher vectors $\bm{\upvarepsilon} \in \set{-1, 1}^{M_1}$,
   \begin{equation}
       (\mathbf{W} - \mathbb{E}[\mathbf{W}], \mathbf{z}_2, \mathbf{b} - \mathbb{E}[\mathbf{b}])
       \overset{\text{d}}{=}
       (\operatorname{diag}(\bm{\upvarepsilon})(\mathbf{W} - \mathbb{E}[\mathbf{W}]), \mathbf{z}_2, \bm{\upvarepsilon} \circ (\mathbf{b} - \mathbb{E}[\mathbf{b}])).
   \end{equation}
   Consider $\mathbf{z}_1 = \tfrac1{\sqrt{M_2}}\mathbf{W} \phi_2(\mathbf{z}_2) + \mathbf{b}$.
   Then
   \begin{align}
       \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
       &\le
           4\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + \norm{\mathbb{E}[\mathbf{W}]}_2^2\, \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty
               + \norm{\mathbb{E}[\mathbf{b}]}_2^2
           )\\
       &\le
           4\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + K^2\, (\norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty \lor 1)
           )
   \end{align}
   provided that $M_1 \ge 3$. 
   If $M_1 < 3$, then the inequality holds with the slightly worse constant $6$.

Set
\begin{align}
    \mathbf{z}_1' &= \mathbf{z}_1 - \tfrac1{\sqrt{M_2}}\mathbb{E}[\mathbf{W}] \phi_2(\mathbf{z}_2) - \mathbb{E}[\mathbf{b}] = \tfrac1{\sqrt{M_2}}(\mathbf{W} - \mathbb{E}[\mathbf{W}])\phi_2(\mathbf{z}_2) + (\mathbf{b} - \mathbb{E}[\mathbf{b}]). \label{eqn:z1'}
\end{align}
Consider
\begin{align}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
    &\le \norm{\mathbb{E}[(\phi_1(\mathbf{z}_1) - \phi_1(\mathbf{z}'_1)) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
    + \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2 \\
    &\overset{\smash{\text{(i)}}}{\le} \mathbb{E}[\norm{(\phi_1(\mathbf{z}_1) - \phi_1(\mathbf{z}'_1)) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}}_2]
    + \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2 \\
    &\overset{\smash{\text{(ii)}}}{=} \mathbb{E}[\norm{\phi_1(\mathbf{z}_1) - \phi_1(\mathbf{z}'_1)}_2 \norm{\phi_1(\mathbf{z}_1)}_2]
    + \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2 \\
    &\overset{\smash{\text{(iii)}}}{\le} \mathbb{E}[\norm{\mathbf{z}_1 - \mathbf{z}'_1}_2 \norm{\mathbf{z}_1}_2] 
    + \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2 \\
    &\overset{\smash{\text{(iv)}}}{\le} (\mathbb{E}[\norm{\mathbf{z}_1 - \mathbf{z}'_1}^2_2] \,\mathbb{E}[\norm{\mathbf{z}_1}^2_2])^{1/2}
    + \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
\end{align}
where in (i) we use Jensen's Inequality, in (ii) we compute the $2$-norm, in (iii) we use 1-Lipschitzness and oddness of $\phi_1$, and in (iv) we use Cauchy--Schwarz.
In a similar way, we can simplify the last term from above:
\begin{equation}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
    \le (\mathbb{E}[\norm{\mathbf{z}'_1}^2_2]\,\mathbb{E}[\norm{\mathbf{z}_1 - \mathbf{z}'_1}^2_2])^{1/2} + \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}'_1)^{\text{\textsf{T}}}]}_2.
\end{equation}
Therefore,
\begin{align}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2 
    \le
        \mathbb{E}[\norm{\mathbf{z}_1 - \mathbf{z}'_1}^2_2]^{1/2}
        (\mathbb{E}[\norm{\mathbf{z}_1}^2_2]^{1/2} + \mathbb{E}[\norm{\mathbf{z}'_1}^2_2]^{1/2})
        + \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}'_1)^{\text{\textsf{T}}}]}_2.\label{eqn:phi1_z1_phi1_z1}
\end{align}
Unfortunately, the square roots cannot be pushed inside: Jensen's inequality is the other way around. Instead, we bound each of the three terms involving $\mathbf{z}'$ in \cref{eqn:phi1_z1_phi1_z1} separately, starting with the first term. Applying the inequality $(a + b)^2 \le 2a^2 + 2b^2$ to \cref{eqn:z1'}, we have
\begin{align}
    \mathbb{E}[\norm{\mathbf{z}_1 - \mathbf{z}'_1}^2_2]
    &\le 2\norm{\mathbb{E}[\mathbf{W}]}_2^2 \tfrac1{M_2} \mathbb{E}[\norm{\phi_2(\mathbf{z}_{2})}^2_2] + 2\norm{\mathbb{E}[\mathbf{b}]}_2^2 \\
    &\le 2\norm{\mathbb{E}[\mathbf{W}]}_2^2 \tfrac1{M_2} \mathbb{E}[\norm{\mathbf{z}_{2}}^2_2] + 2\norm{\mathbb{E}[\mathbf{b}]}_2^2 \label{eqn:use_lipschitz} \\
    &\le 2\norm{\mathbb{E}[\mathbf{W}]}_2^2 \norm{\mathbb{E}[\mathbf{z}_2^2]}_\infty + 2\norm{\mathbb{E}[\mathbf{b}]}_2^2.
\end{align}
Above, the second inequality follows from the oddness and 1-Lipschitzness of $\phi_2$ and that $\norm{\mathbf{1}}_2^2 = M_2$
while the third inequality follows from converting the 2-norm to an $\infty$-norm:
\begin{equation}
\mathbb{E}[\norm{\mathbf{z}_2}_2^2] \le \mathbb{E}\left[\sum_{i=1}^{M_2} z_{2,i}^2\right] = \sum_{i=1}^{M_2} \mathbb{E}[z_{2,i}^2] \le M_2 \norm{\mathbb{E}[\mathbf{z}_2^2]}_\infty. \label{eqn:convert_2_infty}
\end{equation}
Similarly, 
\begin{equation}
    \mathbb{E}[\norm{\mathbf{z}'_1}^2_2]
    \le 3\mathbb{E}[\norm{\mathbf{z}_1}^2_2] + 3\norm{\mathbb{E}[\mathbf{W}]}_2^2\, \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty + 3\norm{\mathbb{E}[\mathbf{b}]}_2^2.
\end{equation}
For convenience, define the expression
\begin{equation}
c = (\norm{\mathbb{E}[\mathbf{W}]}_2^2 \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty + \norm{\mathbb{E}[\mathbf{b}]}_2^2)^{1/2}.
\end{equation}
Using the subadditivity of the square root, we can write the previous two expressions as
\begin{equation}
    \mathbb{E}[\norm{\mathbf{z}_1 - \mathbf{z}'_1}^2_2]^{1/2} \le \sqrt{2}c \label{eqn:z1_minutes_z1'}
\end{equation}
and
\begin{equation}
    \mathbb{E}[\norm{\mathbf{z}'_1}^2_2]^{1/2} \le \sqrt{3}\mathbb{E}[\norm{\mathbf{z}_1}^2_2]^{1/2} + \sqrt{3}c, \label{eqn:z1-2}
\end{equation}
respectively. To bound the last term in \cref{eqn:phi1_z1_phi1_z1}, 
let $\mathbf{w}_m$ denote the $m$\textsuperscript{th} row of $\mathbf{W}$.
Also let $\mathbf{w}_m' = \mathbf{w}_m - \mathbb{E}[\mathbf{w}_m]$ and $\mathbf{b}' = \mathbf{b} - \mathbb{E}[\mathbf{b}]$.
Let $m, m' \in [M_1]$, $m \neq m'$.
By the assumed symmetry condition,
\begin{equation}
    ((\mathbf{w}_m, \mathbf{w}_{m'}), \mathbf{z}_2, (b_m, b_{m'}))
    \overset{\text{d}}{=}
    ((-\mathbf{w}_m, \mathbf{w}_{m'}), \mathbf{z}_2, (-b_m, b_{m'})).
\end{equation}
Therefore, using oddness,
\begin{align}
    -\phi_1(z_{1,m}') \phi_1(z_{1,m'}')
    &=
        -\phi_1(\lra{\tfrac1{M_2}\mathbf{w}_m', \phi_2(\mathbf{z}_2)} + b_m') 
        \phi_1(\lra{\tfrac1{M_2}\mathbf{w}_{m'}', \phi_2(\mathbf{z}_2)} + b_{m'}') \\
    &=
        \phi_1(\lra{-\tfrac1{M_2}\mathbf{w}_m', \phi_2(\mathbf{z}_2)} - b_m') 
        \phi_1(\lra{\tfrac1{M_2}\mathbf{w}_{m'}', \phi_2(\mathbf{z}_2)} + b_{m'}') \\
    &\overset{\text{d}}{=}
        \phi_1(\lra{\tfrac1{M_2}\mathbf{w}_m', \phi_2(\mathbf{z}_2)} + b_m') 
        \phi_1(\lra{\tfrac1{M_2}\mathbf{w}_{m'}', \phi_2(\mathbf{z}_2)} + b_{m'}') \\
    &=\phi_1(z_{1,m}') \phi_1(z_{1,m'}'),
\end{align}
which means that $\mathbb{E}[\phi_1(z_{1,m}') \phi_1(z_{1,m'}')] = 0$. Consequently, the matrix $\mathbb{E}[\phi_1(\mathbf{z}_1') \phi_1(\mathbf{z}_1')^{\text{\textsf{T}}}]$ is diagonal, so
\begin{equation}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}'_1) \phi_1(\mathbf{z}'_1)^{\text{\textsf{T}}}]}_2
    = \relax_{m \in [M_1]}\, \mathbb{E}[\phi_1^2(z'_{1,m})]
    = \norm{\mathbb{E}[\phi_1^2(\mathbf{z}'_{1})]}_\infty.
\end{equation}
To bound $\norm{\mathbb{E}[\phi_1^2(\mathbf{z}'_{1})]}_\infty$, consider that
\begin{align}
    \phi_1^2(\mathbf{z}'_{1})
    &\preceq (\mathbf{z}'_{1})^2 \\
    &\preceq 3 \mathbf{z}^2_{1} + 3 \tfrac1{M_2}(\mathbb{E}[\mathbf{W}] \phi_2(\mathbf{z}_{2}))^2 + 3\,\mathbb{E}[\mathbf{b}]^2 \\
    &\preceq 3 \mathbf{z}^2_{1} + 3 \norm{\mathbb{E}[\mathbf{W}]}_2^2 \tfrac1{M_2}\norm{\phi_2(\mathbf{z}_{2})}_2^2 \mathbf{1} + 3\,\mathbb{E}[\mathbf{b}]^2 \\
    &\preceq 3 \mathbf{z}^2_{1} + 3 \norm{\mathbb{E}[\mathbf{W}]}_2^2 \tfrac1{M_2}\norm{\mathbf{z}_{2}}_2^2 \mathbf{1} + 3\,\mathbb{E}[\mathbf{b}]^2
\end{align}
where the squares and inequalities are element-wise. We use the oddness and 1-Lipschitzness of $\phi_1$ and $\phi_2$ in the first and last inequalities, respectively, and we use the manipulation $\mathbf{A}\mathbf{v} \preceq \norm{\mathbf{A}\mathbf{v}}_\infty \mathbf{1} \preceq \norm{\mathbf{A}\mathbf{v}}_2 \mathbf{1} \preceq \norm{\mathbf{A}}_2\norm{\mathbf{v}}_2 \mathbf{1}$ in the third inequality. Therefore, using that $\norm{\mathbb{E}[\mathbf{b}]}_\infty \le \norm{\mathbb{E}[\mathbf{b}]}_2$, we have
\begin{align}
    \norm{\mathbb{E}[\phi_1^2(\mathbf{z}'_{1})]}_\infty
    &\le
        3 \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
        + 3 \norm{\mathbb{E}[\mathbf{W}]}_2^2 \tfrac1{M_2}\mathbb{E}[\norm{\mathbf{z}_{2}}_2^2]
        + 3 \norm{\mathbb{E}[\mathbf{b}]}_\infty^2 \\
    &=
        3 \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + 3 c^2 \label{eqn:phi2z1'}
\end{align}
We can now plug the bounds on the $\mathbf{z}_1'$ terms, given by Equations (\ref{eqn:z1_minutes_z1'}), (\ref{eqn:z1'}), and (\ref{eqn:phi2z1'}), into \cref{eqn:phi1_z1_phi1_z1}:
\begin{align}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
    &\le
        \sqrt{2}c \left((1+\sqrt{3})\mathbb{E}[\norm{\mathbf{z}_1}^2_2]^{1/2} + \sqrt{3}c\right) + 3 \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + 3 c^2 \\
    &\le
        \sqrt{2}(1+\sqrt{3})\mathbb{E}[\norm{\mathbf{z}_1}^2_2]^{1/2} c
        + (3+\sqrt{6})( \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + c^2) \\
    &\le
        \sqrt{2}(1+\sqrt{3})\sqrt{M_1}\norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty^{1/2} c + (3+\sqrt{6})( \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + c^2),
\end{align}
where we add an extra $2\sqrt{3}\norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty$ term to more simply group the terms in second inequality and we covert the 2-norm of $\mathbf{z}_2$ to an $\infty$-norm in the third inequality, as in \cref{eqn:convert_2_infty}. Next, since $2ab + a^2 + b^2 = (a + b)^2 \le 2a^2 + 2b^2 \implies ab \le \tfrac12(a^2 + b^2)$, we can simplify the following expression in the first term above as
\begin{equation}
    \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty^{1/2} c \le \tfrac{1}{2}( \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + c^2).
\end{equation}
Therefore, 
\begin{align}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
    &\le
        \tfrac12\sqrt{2}(1+\sqrt{3})\sqrt{M_1}( \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + c^2)
        + (3+\sqrt{6})(\norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + c^2) \\
    &\le
        \left(\tfrac12\sqrt{2}(1+\sqrt{3})\sqrt{M_1} + (3+\sqrt{6}) \right)
        (\tfrac12\norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + c^2) 
\end{align}
If $M_1 \ge 3$, then $(3+\sqrt{6}) \le \tfrac12\sqrt{2}(1+\sqrt{3}) \sqrt{M_1}$, so we have
\begin{align}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
    &\le
        \sqrt{2}(1+\sqrt{3})\sqrt{M_1}( \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty + c^2 \\
    &\le
        4\sqrt{M_1} ( \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty^{1/2} + \norm{\mathbb{E}[\mathbf{W}]}_2^2 \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty + \norm{\mathbb{E}[\mathbf{b}]}_2^2).
\end{align}
Otherwise, if $M_1 < 3$, then the inequality holds with the slightly worse constant $\sqrt{2}(1+\sqrt{3}) +  (3+\sqrt{6}) \approx 7.4 \le 8$:
\begin{align}
    \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
    &\le
        8\sqrt{M_1} ( \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty^{1/2} + \norm{\mathbb{E}[\mathbf{W}]}_2^2 \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty + \norm{\mathbb{E}[\mathbf{b}]}_2^2).
\end{align}

\label{rem:outer_offset}
   The symmetry condition for $(\mathbf{W}, \mathbf{z}_2, \mathbf{b})$ is satisfied if $\mathbf{W}$ and $\mathbf{b}$, not $\mathbf{z}_2$, are element-wise independent and symmetric around their means.
   For such $(\mathbf{W}, \mathbf{z}_2, \mathbf{b})$, the symmetry condition is also satisfied for the triple $(\mathbf{W}, \mathbf{z}_2, \tfrac{\alpha}{\sqrt{M_2}} \mathbf{W} \mathbf{1} + \mathbf{b})$
   where $\mathbf{1}$ is the vector of all ones and $\alpha \in \mathbb{R}$.
   In that case, a similar conclusion holds:
   if instead
   \begin{equation}
       \mathbf{z}_1
           = \tfrac1{\sqrt{M_2}}\mathbf{W} (\phi_2 + \alpha)(\mathbf{z}_2) + \mathbf{b}
           = \tfrac1{\sqrt{M_2}}\mathbf{W} \phi_2 (\mathbf{z}_2) + (\tfrac{\alpha}{\sqrt{M_2}} \mathbf{W} \mathbf{1} + \mathbf{b}),
   \end{equation}
   then, if $M_1\ge 3$, by \cref{lem:outer} 
   \begin{align}
       \norm{\mathbb{E}[\phi_1(\mathbf{z}_1) \phi_1(\mathbf{z}_1)^{\text{\textsf{T}}}]}_2
       &\le
           4\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + \norm{\mathbb{E}[\mathbf{W}]}_2^2\, \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty
               + \norm{\mathbb{E}[\tfrac{\alpha}{\sqrt{M_2}} \mathbf{W} \mathbf{1} + \mathbf{b}]}_2^2
           )\\
       &\le
           4\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + \norm{\mathbb{E}[\mathbf{W}]}_2^2\, \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty
               + \tfrac{2\alpha^2}{M_2} \norm{\mathbb{E}[\mathbf{W}]}_2^2 \norm{\mathbf{1}}_2^2 + 2\norm{\mathbb{E}[\mathbf{b}]}_2^2
           )\\
       &\overset{\smash{\text{(i)}}}{\le}
           4\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + \norm{\mathbb{E}[\mathbf{W}]}_2^2 (2 \alpha^2 + \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty) + 2\norm{\mathbb{E}[\mathbf{b}]}_2^2
           )\\
       &\le
           8\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + \norm{\mathbb{E}[\mathbf{W}]}_2^2 (\alpha^2 + \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty) + \norm{\mathbb{E}[\mathbf{b}]}_2^2
           )\\
       &\overset{\smash{\text{(ii)}}}{\le}
           8\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + K^2\, ((\alpha^2 +  \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty) \lor 1)
           ) \\
       &\le
           8\sqrt{M_1}(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
               + K^2\, (\alpha^2 + 1 \lor \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty)
           )
   \end{align}
   where in (i) we use that $\norm{\mathbf{1}}_2^2 = M_2$ and in (ii) we use that $\norm{\mathbb{E}[\mathbf{W}]}_2^2 + \norm{\mathbb{E}[\mathbf{b}]}_\infty^2 \le K^2$. If $M_1<3$, then the inequality holds with the slightly worse constant of 12.

Let $m \in [M_2]$, and let $\mathbf{w}_m$ denote the $m$\textsuperscript{th} row of $\mathbf{W}$, so that $z_{1,m}=\tfrac{1}{\sqrt{M_2}}\mathbf{w}_m^T\phi_2(\mathbf{z}_2) + b_m$. Using $(a + b)^2\le 2a^2 + 2b^2$,
\begin{align}
    \mathbb{E}[z_{1,m}^2]
    &\le \tfrac2{M_2}\,\mathbb{E}[(\mathbf{w}_m^T \phi_2(\mathbf{z}_2))^2] + 2\,\mathbb{E}[b_{m}^2] \\
    &\le \tfrac2{M_2} \lra{\mathbb{E}[\mathbf{w}_m^2], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]} + C + 2\,\mathbb{E}[b_{m}^2] \\
    &= \tfrac2{M_2} \lra{\mathbb{V}\ss{d}[\mathbf{w}_m], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]} + C + \tfrac2{M_2} \lra{\mathbb{E}^2[\mathbf{w}_m], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}  + 2\,\mathbb{E}[b_{m}^2],
\end{align}
where $C$ is the sum of the off-diagonal terms of $\tfrac2{M_2}\mathbb{E}[(\mathbf{w}_m^T \phi_2(\mathbf{z}_2))^2]$. 
Hence, by the triangle inequality,
\begin{align}
    \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty
    &\le \tfrac2{M_2} \relax_m \{\abs{\lra{\mathbb{V}\ss{d}[\mathbf{w}_m], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}} \} + \relax_m \{\abs{C + \tfrac2{M_2} \lra{\mathbb{E}^2[\mathbf{w}_m], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}}\} + 2\, \norm{\mathbb{E}[\mathbf{b}^2]}_\infty. \label{eqn:z1_infty}
\end{align}
Consider the middle term in \cref{eqn:z1_infty}. We have
\begin{align}
    C + \tfrac2{M_2} \lra{\mathbb{E}^2[\mathbf{w}_m], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}

    &= \tfrac2{M_2} \lra{\mathbb{E}[\mathbf{w}_m], \mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}] \mathbb{E}[\mathbf{w}_m]} \\
    &\le \tfrac2{M_2} \norm{\mathbb{E}[\mathbf{w}_m]}_2^2 \norm{\mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}]}_2,
\end{align}
where the second inequality follows from the Cauchy-Schwarz inequality and the definition of the operator norm. Therefore,
\begin{align}
    \relax_m \{ \abs{C + \tfrac2{M_2} \lra{\mathbb{E}^2[\mathbf{w}_m], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]} } \}
    &\le \tfrac2{M_2} \relax_m \{ \norm{\mathbb{E}[\mathbf{w}_m]}_2^2 \} \norm{\mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}]}_2 \\
    &\le \tfrac2{M_2} \norm{\mathbb{E}[\mathbf{W}]}\ss{F}^2 \norm{\mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}]}_2.
\end{align}
To bound the first term in \cref{eqn:z1_infty}, use the H{\"o}lder inequality with the conjugate pair $(\infty, 1)$:
\begin{align}
    \tfrac2{M_2} \relax_m \{\abs{\lra{\mathbb{V}\ss{d}[\mathbf{w}_m], \mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}} \} 
    &\le \tfrac2{M_2} \relax_m \{ \norm{\mathbb{V}\ss{d}[\mathbf{w}_m]}_\infty \norm{\mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}_1 \} \\
    &= \tfrac2{M_2} \relax_m \{ \norm{\mathbb{V}\ss{d}[\mathbf{w}_m]}_\infty \} \norm{\mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}_1 \\
    &= \tfrac2{M_2} \norm{\mathbb{V}\ss{d}[\operatorname{vec}(\mathbf{W})]}_\infty \norm{\mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}_1.
\end{align}
Notice that since $\phi_2$ is 1-Lipschitz and odd, we can write
\begin{align}
    \norm{\mathbb{E}[\phi_2^2(\mathbf{z}_{2})]}_1
    = \norm{\mathbb{E}[\abs{\phi_2(\mathbf{z}_{2}) - \phi_2(\mathbf{0}) }^2]}_1
    \le \norm{\mathbb{E}[\abs{\mathbf{z}_{2} - \mathbf{0}}^2]}_1
    = \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_1.
\end{align}
Plugging into \cref{eqn:z1_infty},  we have
\begin{align}
    \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty 
    &\le \tfrac2{M_2} \norm{\mathbb{V}\ss{d}[\operatorname{vec}(\mathbf{W})]}_\infty \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_1
    + \tfrac2{M_2} \norm{\mathbb{E}[\mathbf{W}]}\ss{F}^2 \norm{\mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}]}_2
    + 2 \norm{\mathbb{E}[\mathbf{b}^2]}_\infty \\
    &\le
        2(
        \norm{\mathbb{V}\ss{d}[\operatorname{vec}(\mathbf{W})]}_\infty
            + \norm{\mathbb{E}[\mathbf{b}^2]}_\infty
        ) (1 \lor \tfrac1{M_2} \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_1)
        + \tfrac2{M_2} \norm{\mathbb{E}[\mathbf{W}]}\ss{F}^2 \norm{\mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}]}_2.
\end{align}
The result follows by applying \cref{lem:parameter_bound} and \cref{prop:optimised_param_bound}.
Similarly, using $\norm{\mathbb{E}[\mathbf{z}_{2}^2]}_1 \le M_2 \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty$, we can again plug into \cref{eqn:z1_infty} to obtain
\begin{align}
    \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty 
    &\le 2 \norm{\mathbb{V}\ss{d}[\operatorname{vec}(\mathbf{W})]}_\infty \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty
    + \tfrac2{M_2} \norm{\mathbb{E}[\mathbf{W}]}\ss{F}^2 \norm{\mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}]}_2
    + 2 \norm{\mathbb{E}[\mathbf{b}^2]}_\infty \\
    &\le
        2(
        \norm{\mathbb{V}\ss{d}[\operatorname{vec}(\mathbf{W})]}_\infty
            + \norm{\mathbb{E}[\mathbf{b}^2]}_\infty
        ) (1 \lor \norm{\mathbb{E}[\mathbf{z}_{2}^2]}_\infty)
        + \tfrac2{M_2} \norm{\mathbb{E}[\mathbf{W}]}\ss{F}^2 \norm{\mathbb{E}[\phi_2(\mathbf{z}_{2})\phi_2(\mathbf{z}_{2})^{\text{\textsf{T}}}]}_2.
\end{align}

\label{lem:z-squared-recursion}
    For $\alpha=0$ and $1 \leq \ell \leq L$, we have
    \begin{equation}
        \norm{\mathbb{E}[\mathbf{z}_\ell^2]}_\infty \leq (\gamma_{\alpha, M} (1 \lor K^2))^{\ell} (1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2),
    \end{equation}
    with $\gamma_{\alpha, M}$ taking the value $\tfrac23(13+2\sqrt{43} \in (17,18)$ if $M\ge 36$ and $2(6+\sqrt{38}) \in (24,25)$ if $1\le M < 36$.
    On the other hand, for $\alpha \neq 0$ and $1 \leq \ell \le L$, we have
    \begin{equation}
        \alpha^2 + \norm{\mathbb{E}[\mathbf{z}_\ell^2]}_\infty \leq (\gamma_{\alpha, M} (1 \lor K^2))^{\ell} (\alpha^2 + 1\lor \tfrac1{D\ss{i}} \|\mathbf{x}\|^2_2),
    \end{equation}
    with $\gamma_{\alpha, M}$ taking the value $28 + \sqrt{793} \in (56,57)$ if $M\ge 36$ and $48 + \sqrt{2353} \in (96,97)$ if $1\le M < 36$.

For notational convenience, define $a_\ell = 1 \lor  \norm{\mathbb{E}[\mathbf{z}_\ell^2]}_\infty$ and $b_\ell = \norm{\mathbb{E}[\phi(\mathbf{z}_{\ell})\phi(\mathbf{z}_{\ell})^{\text{\textsf{T}}}]}_2$.
Also take $a_0 = 1\lor \|\mathbf{x}\|^2_2$. 
Apply \cref{lem:inf} with $\phi_2$ given by the identity function and $\mathbf{z}_2 = \mathbf{x}$.
Then
\begin{align}
    a_1 &\leq 2\left((\sqrt{2}+K)^2
            (1 \lor \tfrac1{D\ss{i}}\norm{\mathbf{x}^2}_1) 
            + \tfrac1{D\ss{i}} K^2 \norm{\mathbf{x}\mathbf{x}^{\text{\textsf{T}}}}_2 \right) \\
        &\le 2\left(8(1 \lor K)^2
            (1 \lor \tfrac1{D\ss{i}}\norm{\mathbf{x}}_2^2) 
            + \tfrac1{D\ss{i}} K^2 \|\mathbf{x}\|_2^2 \right) \\
        & \leq 18(1 \lor K^2)(1 \lor \tfrac1{D\ss{i}}\norm{\mathbf{x}}^2_2) 
\end{align}
where the second inequality follows from $\sqrt{2} + K \le \sqrt{2}(1 + K) \le 2\sqrt{2}(1 \lor K)$ and $\norm{\mathbf{x}\mathbf{x}^{\text{\textsf{T}}}}_2 = \norm{\mathbf{x}}_2^2$.

By \cref{lem:inf} we have
\begin{align}
    a_\ell \leq  2\left((\sqrt{2}+K)^2
            a_{\ell-1} 
            + \tfrac1M K^2 b_{\ell-1} \right).
\end{align}
Further, by \cref{lem:outer}, we have
\begin{align}
    b_{\ell-1} \leq 4\sqrt{M}(a_{\ell-1}
                + K^2\, a_{\ell-2}) .
\end{align}
Combining these estimates yields
\begin{align}
     a_\ell &\leq  2\left((\sqrt{2}+K)^2
            a_{\ell-1}
            + \tfrac{4}{\sqrt{M}} K^2 \left(a_{\ell-1}
                + K^2 a_{\ell-2}\right. \right) \\
        & \leq       2\left(8(1\lor K^2)
             a_{\ell-1}
            + \tfrac{4}{\sqrt{M}} K^2 \left(a_{\ell-1}
                + K^2 a_{\ell-2}\right) \right) \\
         & \le
            (16+\tfrac8{\sqrt{M}}) (1 \lor K^2) a_{\ell-1}
            + \tfrac8{\sqrt{M}} (1 \lor K^4) a_{\ell-2}.
\end{align}


Assuming $M \ge 36$, we further simplify
\begin{align}
     a_\ell
     &\leq
        (16+\tfrac43) (1 \lor K^2) a_{\ell-1}
        + \tfrac43 (1 \lor K^4) a_{\ell-2}. \label{eqn:second_order_recursion}
\end{align}
We choose $M \ge 36$ for convenience when subsequently applying this lemma. We will return to the general case of $M \ge 1$ later. First, notice 
\cref{eqn:second_order_recursion} is a homogeneous second-order linear recurrence relation.
By finding the roots of the characteristic polynomial associated to this recurrence relation,  
\begin{align}
    a_{\ell} \leq c_0\Big(\gamma (1 \lor K^2)\Big)^{\ell} 

\end{align}
for some $c_0$ and $\gamma = \tfrac23(13+2\sqrt{43} \in (17,18)$, which can be proved by induction. Checking initial conditions, we see that we can take $c_0 = 1\lor \|\mathbf{x}\|^2 $, yielding the bound
\begin{align}
      a_{\ell}
      &\leq \Big(\gamma(1 \lor K^2)\Big)^{\ell} (1\lor \tfrac1{D\ss{i}} \|\mathbf{x}\|^2_2).
\end{align}
On the other hand, if $1 \le M < 36$, by the same reasoning the bound holds with constant $\gamma = 2(6+\sqrt{38}) \in (24,25)$.

\begin{align}
         a_\ell &\leq  2\left((\sqrt{2}+K)^2
                a_{\ell-1}
                + \tfrac{4}{\sqrt{M}} K^2 \left(a_{\ell-1}
                    + K^2 a_{\ell-2}\right. \right) \\
            & \leq       2\left(8(1\lor K^2)
                 a_{\ell-1}
                + \tfrac{4}{\sqrt{M}} K^2 \left(a_{\ell-1}
                    + K^2 a_{\ell-2}\right) \right) \\
             & \le
                (16+\tfrac8{\sqrt{M}}) (1 \lor K^2) a_{\ell-1}
                + \tfrac8{\sqrt{M}} (1 \lor K^4) a_{\ell-2}.
    \end{align}

The proof for the case $\alpha \neq 0$ proceeds like the case $\alpha = 0$, but uses \cref{rem:outer_offset,rem:inf_offset} instead of \cref{lem:outer,lem:inf}.
Analogously define $a_\ell = \alpha^2 + 1 \lor \norm{\mathbb{E}[\mathbf{z}_\ell^2]}_\infty$,
$a_0 = \alpha^2 + 1 \lor \norm{\mathbf{x}}^2_2$,
and $b_\ell = \norm{\mathbb{E}[\phi(\mathbf{z}_\ell)\phi(\mathbf{z}_\ell)^{\text{\textsf{T}}}]}_2$.
To begin with, apply \cref{rem:inf_offset} with $\phi_2$ given by the identity function and $\mathbf{z}_2 = \mathbf{x}$:
\begin{align}
    a_1
    &\le \alpha^2 + 6(\sqrt{2} + K)^2(\alpha^2 + 1 \lor \tfrac1{D\ss{i}}\norm{\mathbf{x}^2}_1)+ 6K^2(\alpha^2 + \tfrac1{D\ss{i}} \norm{\mathbf{x} \mathbf{x}^{\text{\textsf{T}}}}_2) \\
    &\le 48(1 \lor K^2)(\alpha^2 + 1 \lor \tfrac1{D\ss{i}}\norm{\mathbf{x}}_2^2)+ 7K^2(\alpha^2 + \norm{\mathbf{x}}^2_2) \\
    &\le 55(1 \lor K^2)(\alpha^2 + 1 \lor \tfrac1{D\ss{i}}\norm{\mathbf{x}}^2_2).
\end{align}
For $1 < \ell \le L$,
\begin{align}
    a_\ell
    &\le
        \alpha^2
        + 48(1 \lor K^2)a_{\ell - 1}
        + 6K^2(\alpha^2 + \tfrac1{M}b_{\ell-1}).




\end{align}
By \cref{rem:outer_offset},
\begin{align}
    b_{\ell - 1} \le 8 \sqrt{M} (\norm{\mathbb{E}[\mathbf{z}_{\ell-1}^2]}_\infty + K^2 a_{\ell - 2}).
\end{align}
Plugging the expression for $b_{\ell-1}$ into the expression for $a_\ell$,
\begin{align}
    a_\ell
    &\le
        \alpha^2
        + 48(1 \lor K^2)a_{\ell - 1}
        + 6K^2(\alpha^2 + \tfrac{8}{\sqrt{M}}(\norm{\mathbb{E}[\mathbf{z}_{\ell-1}^2]}_\infty + K^2 a_{\ell - 2})) \\
    &\le
        \alpha^2
        + 48(1 \lor K^2)a_{\ell - 1}
        + 6(1 \lor 8M^{-1/2})K^2(\alpha^2 + \norm{\mathbb{E}[\mathbf{z}_{\ell-1}^2]}_\infty + K^2 a_{\ell - 2}) \\
    &\le
        \alpha^2
        + 48(1 \lor K^2)a_{\ell - 1}
        + 6(1 \lor 8M^{-1/2})K^2(a_{\ell - 1} + K^2 a_{\ell - 2}) \\
    &\le
        \alpha^2
        + (48 + 6(1 \lor 8M^{-1/2}))(1 \lor K^2)a_{\ell - 1}
        + 6(1 \lor 8M^{-1/2}) (1 \lor K^4) a_{\ell - 2} \\
    &\le
        (48 + 6(1 \lor 8M^{-1/2}) )(1 \lor K^2)a_{\ell - 1}
        + (1 + 6(1 \lor 8M^{-1/2})) (1 \lor K^4) a_{\ell - 2} .
\end{align}
As in the $\alpha=0$ case, we first consider the case $M\ge36$, giving
\begin{equation}
    a_\ell
    \le
        56(1 \lor K^2)a_{\ell - 1}
        + 9 (1 \lor K^4) a_{\ell - 2} .
\end{equation}

This is again a homogeneous second-order linear recurrence relation.
Solving for the roots of the characteristic polynomial, we find that
\begin{equation}
    a_{\ell} \le c_0 \Big(\gamma' (1 \lor K^2)\Big)^\ell,
\end{equation}
for some $c_0$ and $\gamma' = 28 + \sqrt{793} \in (56,57)$.
Comparing with the bound on $a_1$, we see that $c_0 = \alpha^2 + 1 \lor \tfrac1{D\ss{i}}\norm{\mathbf{x}}_2^2$. On the other hand, if $1\le M < 36$, by the same reasoning the bound holds with $\gamma' = 48 + \sqrt{2353} \in (96,97)$.

\begin{align}
        a_\ell
        &\le
            \alpha^2
            + 48(1 \lor K^2)a_{\ell - 1}
            + 6K^2(\alpha^2 + \tfrac{8}{\sqrt{M}}(\norm{\mathbb{E}[\mathbf{z}_{\ell-1}^2]}_\infty + K^2 a_{\ell - 2})) \\
        &\le
            \alpha^2
            + 48(1 \lor K^2)a_{\ell - 1}
            + 6(1 \lor 8M^{-1/2})K^2(\alpha^2 + \norm{\mathbb{E}[\mathbf{z}_{\ell-1}^2]}_\infty + K^2 a_{\ell - 2}) \\
        &\le
            \alpha^2
            + 48(1 \lor K^2)a_{\ell - 1}
            + 6(1 \lor 8M^{-1/2})K^2(a_{\ell - 1} + K^2 a_{\ell - 2}) \\
        &\le
            \alpha^2
            + (48 + 6(1 \lor 8M^{-1/2}))(1 \lor K^2)a_{\ell - 1}
            + 6(1 \lor 8M^{-1/2}) (1 \lor K^4) a_{\ell - 2} \\
        &\le
            (48 + 6(1 \lor 8M^{-1/2}) )(1 \lor K^2)a_{\ell - 1}
            + (1 + 6(1 \lor 8M^{-1/2})) (1 \lor K^4) a_{\ell - 2} .
    \end{align}

\label{lem:cov}
   Let $\phi_1, \phi_2 \colon\mathbb{R} \to \mathbb{R}$ be $1$-Lipschitz and odd and $\alpha \in \mathbb{R}$.
   Let the triple $(\mathbf{W}, \mathbf{z}_2, \mathbf{b}) \in \mathbb{R}^{M_1\times M_2} \times \mathbb{R}^{M_2} \times \mathbb{R}^{M_1}$ be (possibly dependent) random variables such that, for all Rademacher vectors $\bm{\upvarepsilon} \in \set{-1, 1}^{M_1}$,
   \begin{equation}
       (\mathbf{W} - \mathbb{E}[\mathbf{W}], \mathbf{z}_2, \mathbf{b} - \mathbb{E}[\mathbf{b}])
       \overset{\text{d}}{=}
       (\operatorname{diag}(\bm{\upvarepsilon})(\mathbf{W} - \mathbb{E}[\mathbf{W}]), \mathbf{z}_2, \bm{\upvarepsilon} \circ (\mathbf{b} - \mathbb{E}[\mathbf{b}])).
   \end{equation}
   Consider $\mathbf{z}_1 = \tfrac1{\sqrt{M_2}}\mathbf{W} (\phi_2 + \alpha)(\mathbf{z}_2) + \mathbf{b}$.
   Let $m, m' \in [M_1]$, $m \neq m'$.
   Then
   \begin{equation}
       \abs{\mathbb{E}[\phi_1(z_{1,m}) \phi_1(z_{1,m'})]}
       \le
           5(
               \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty^{1/2}
               + 
           )(\alpha^2 + 1 \lor \norm{ \mathbb{E}[\mathbf{z}_2^2] }_\infty)^2(K \lor K^2).
   \end{equation}

The proof of this lemma uses exactly the same approach as \cref{lem:outer}.
Set
\begin{align}
    \mathbf{z}_1' &= \mathbf{z}_1 - \tfrac1{\sqrt{M_2}}\mathbb{E}[\mathbf{W}] (\phi_2 + \alpha)(\mathbf{z}_2) - \mathbb{E}[\mathbf{b}].
\end{align}
Consider
\begin{align}
    \abs{\mathbb{E}[\phi_1(z_{1,m}) \phi_1(z_{1,m'})]}
    &\le
        \sqrt{\mathbb{E}[(\phi_1(z_{1,m}) - \phi_1(z'_{1,m}))^2] \mathbb{E}[\phi^2_1(z_{1,m'})]}
        + \abs{\mathbb{E}[\phi_1(z'_{1,m}) \phi_1(z_{1,m'})]} \\
    &\le \sqrt{ab} +\abs{\mathbb{E}[\phi_1(z'_{1,m}) \phi_1(z_{1,m'})]}
\end{align}
where we denote
\begin{equation}
    a = \norm{\mathbb{E}[\mathbf{z}^2_{1}]}_\infty,
    \quad
    b = \norm{\mathbb{E}[(\mathbf{z}_{1} - \mathbf{z}'_{1})^2]}_\infty.
\end{equation}
Similarly,
\begin{align}
    \abs{\mathbb{E}[\phi_1(z'_{1,m}) \phi_1(z_{1,m'})]}
    &\le
        \sqrt{
            \mathbb{E}[\phi^2_1(z'_{1,m})]
            \mathbb{E}[(\phi_1(z_{1,m'}) - \phi_1(z'_{1,m'}))^2] 
        }
        + \abs{\mathbb{E}[\phi_1(z'_{1,m}) \phi_1(z'_{1,m'})]}.
\end{align}
Now bound
\begin{equation}
    \phi_1^2(\mathbf{z}'_{1})
    \preceq (\mathbf{z}'_{1})^2
    \preceq 2 \mathbf{z}^2_{1} + 2 (\mathbf{z}_1 - \mathbf{z}_1')^2,
\end{equation}
so
\begin{align}
    \sqrt{
        \mathbb{E}[\phi^2_1(z'_{1,m})]
        \mathbb{E}[(\phi_1(z_{1,m'}) - \phi_1(z'_{1,m'}))^2] 
    }
    \le \sqrt{(2a + 2b) b}.
\end{align}
Therefore,
\begin{equation}
    \abs{\mathbb{E}[\phi_1(z_{1,m}) \phi_1(z_{1,m'})]}
    \le \sqrt{ab} + \sqrt{(2a + 2b)b} + \cancel{\abs{\mathbb{E}[\phi_1(z'_{1,m}) \phi_1(z'_{1,m'})]}}
\end{equation}
where the expectation on the RHS is zero by the assumed symmetry condition and oddness of $\phi$.
Breaking up the square root, we find that
\begin{equation}
    \abs{\mathbb{E}[\phi_1(z_{1,m}) \phi_1(z_{1,m'})]}
    \le (\sqrt{2} + 1)\sqrt{ab} + \sqrt{2} b.
\end{equation}
We finally estimate $b$:
\begin{equation}
    \mathbb{E}[(\mathbf{z}_1 - \mathbf{z}_1')^2]
    \preceq \norm{\mathbb{E}[\mathbf{W}]}_2^2 \tfrac{1}{M_2}\mathbb{E}[ \norm{(\phi_2 + \alpha)^2(\mathbf{z}_2)}_2 ] \mathbf{1} + \norm{\mathbb{E}[\mathbf{b}]}_2^2 \mathbf{1}.
\end{equation}
Therefore
\begin{align}
    b
    &\le \norm{\mathbb{E}[\mathbf{W}]}\ss{F}^2 \norm{\mathbb{E}[(\phi_2 + \alpha)^2(\mathbf{z}_2)]}_\infty + \norm{\mathbb{E}[\mathbf{b}]}_2^2 \\
    &\le 2\norm{\mathbb{E}[\mathbf{W}]}\ss{F}^2 (\alpha^2 + \norm{\mathbb{E}[\mathbf{z}_2^2]}_\infty) + \norm{\mathbb{E}[\mathbf{b}]}_2^2 \\
    &\le 2 K^2 (\alpha^2 + 1 \lor \norm{\mathbb{E}[\mathbf{z}_2^2]}_\infty),
\end{align}
which implies that
\begin{equation}
    \abs{\mathbb{E}[\phi_1(z_{1,m}) \phi_1(z_{1,m'})]}
    \le
        (
            (\sqrt{2}+1) \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty^{1/2}
            + \sqrt{2}
        )(\sqrt{b} \lor b),
    \quad
    b = 2 K^2 (\alpha^2 + 1 \lor \norm{ \mathbb{E}[\mathbf{z}_2^2] }_\infty).
\end{equation}
Simplify the estimate to get the result:
\begin{equation}
    \abs{\mathbb{E}[\phi_1(z_{1,m}) \phi_1(z_{1,m'})]}
    \le
        5(
            \norm{\mathbb{E}[\mathbf{z}_1^2]}_\infty^{1/2}
            + 
        )(\alpha^2 + 1 \lor \norm{ \mathbb{E}[\mathbf{z}_2^2] }_\infty)^2(K \lor K^2).
\end{equation}

