\label{lem:diag-frob-norm}
    We have,
    \begin{align}
        \|\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})^2 ]- \mathbb{E}_{\ensuremath{P}}[\phi\ss{o}(\mathbf{z}_{L})^2]\|_2
        &\le 8 \sqrt{2} \rho_{\alpha, M}^{L-\tfrac12} L^{1/2} K (K^2 \lor 1)^{L-\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right),
    \end{align}
    where $K = \sqrt{2 \operatorname{KL}(\ensuremath{Q}, \ensuremath{P})}$ and 
    \begin{equation}
        \rho_{\alpha, M} =
        \begin{cases}
        12(2+\sqrt{2\pi}) \in (54,55) & \alpha=0, M<36 \\
        \tfrac23(13+2\sqrt{43}) \in (17,18) & \alpha=0, M\ge 36 \\
        28 + \sqrt{793} \in (56,57) & \alpha\neq 0, M<36 \\
        48 + \sqrt{2353} \in (96,97) & \alpha\neq 0, M\ge 36. \\
    \end{cases}
\end{equation}

We would like to combine the two expectations into a single expectation. To do this, we couple $\phi(\mathbf{z}_{\ell})^2$ under $\ensuremath{P}$ and $\ensuremath{Q}$ by using the reparameterization trick and having them share the same noise. In particular, for $2 \leq \ell \le L$,  define
\begin{align}
     \mathbf{z}^P_l&= \tfrac1{\sqrt{M}}\mathbfcal{E} \phi\ss{o}(\mathbf{z}^P_{l-1}) + \tfrac{\alpha}{\sqrt{M}}\mathbfcal{E}\mathbf{1} + \bm{\upvarepsilon}, \\
    \mathbf{z}^Q_L
    &= \tfrac1{\sqrt{M}}(\mathbf{S}^Q_l \circ \mathbfcal{E} + \mathbf{M}^Q_l) \phi\ss{o}(\mathbf{z}^Q_{l-1}) + \tfrac{\alpha}{\sqrt{M}}(\mathbf{S}^Q_l \circ \mathbfcal{E} + \mathbf{M}^Q_l)\mathbf{1} + (\mathbf{s}^Q_l \circ \bm{\upvarepsilon} + \mathbf{m}^Q_l).
\end{align}
where $\mathbfcal{E}$ is a matrix of i.i.d.~standard Gaussian random variables, $\bm{\upvarepsilon}$ is a vector of i.i.d.~standard Gaussian random variables, $\mathbf{M}^Q_L$ is a matrix consisting of the mean of each weight in layer $L$ under $\ensuremath{Q}$, $\mathbf{m}^Q_L$ is vector consisting of the mean of each bias in layer $L$ under $\ensuremath{Q}$, $\mathbf{S}^Q_L$ and $\mathbf{s}^Q_L$ are a matrix and vector containing the standard deviations of each weight or bias respectively in layer $L$ under $\ensuremath{Q}$. We then can rewrite,
\begin{align}
    \|\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})^2 ]- \mathbb{E}_{\ensuremath{P}}[\phi\ss{o}(\mathbf{z}_{L})^2]\|_2 &= \norm{\mathbb{E}[\phi\ss{o}(\mathbf{z}^Q_L)^2 - \phi\ss{o}(\mathbf{z}^P_L)^2]}_2 
    \\
    & = \sqrt{\sum_{m=1}^M \left(\mathbb{E}[(\phi\ss{o}(z^Q_{m,L}) + \phi\ss{o}(z^P_{m, L})) (\phi\ss{o}(z^Q_{m, L}) - \phi\ss{o}(z^P_{m,L})))]\right)^2 } 
    \\
    & \leq \sqrt{\sum_{m=1}^M\mathbb{E}[(\phi\ss{o}(z^Q_{m,L}) + \phi\ss{o}(z^P_{m, L}))^2]\mathbb{E}[(\phi\ss{o}(z^Q_{m,L}) - \phi\ss{o}(z^P_{m, L}))^2]}
    \\
    & \leq \sqrt{\norm*{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) + \phi\ss{o}(\mathbf{z}^P_L))^2]}_\infty} \sqrt{\sum_{m=1}^M \mathbb{E}[(\phi\ss{o}(z^Q_{m,L}) - \phi\ss{o}(z^P_{m, L}))^2]}
    \\
    & = \sqrt{\norm{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) + \phi\ss{o}(\mathbf{z}^P_L))^2]}_\infty} \sqrt{ \mathbb{E}[ \norm{\phi\ss{o}(\mathbf{z}^Q_L) - \phi\ss{o}(\mathbf{z}^P_L)}^2_2] }
    \\
    &\le \sqrt{\norm{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) + \phi\ss{o}(\mathbf{z}^P_L))^2]}_\infty} \sqrt{ \mathbb{E}[ \norm{\mathbf{z}^Q_L - \mathbf{z}^P_L}^2_2] }
    \label{eqn:phi2Q_phi2P}
\end{align}
The first inequality is an element-wise application of Cauchy-Schwarz viewing the expectation as an inner product, the second inequality is a bound of the form $\sum |a_i b_i| \leq \relax |a_i| \sum |b_i|$, and the third inequality uses the Lipschitz property of $\phi\ss{o}$. We next bound the square of each of the two terms in \cref{eqn:phi2Q_phi2P}.

\paragraph{Bounding $\norm{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) + \phi\ss{o}(\mathbf{z}^P_L))^2]}_\infty$.} Using the inequality $(a_1+a_2)^2 \le 2(a_1^2 + a_2^2)$ and the triangle inequality we have
\begin{align}
    \norm{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) + \phi\ss{o}(\mathbf{z}^P_L))^2]}_\infty
    &\le \norm{\mathbb{E}[2\phi\ss{o}^2(\mathbf{z}^Q_L) + 2\phi\ss{o}^2(\mathbf{z}^P_L)]}_\infty \\
    &\le 2\norm{\mathbb{E}[\phi\ss{o}^2(\mathbf{z}^Q_L)]}_\infty + 2\norm{\mathbb{E}[\phi\ss{o}^2(\mathbf{z}^P_L)]}_\infty \\
    &\le 2\norm{\mathbb{E}[(\mathbf{z}^Q_L)^2]}_\infty + 2\norm{\mathbb{E}[(\mathbf{z}^P_L)^2]}_\infty,
\end{align}
where the last inequality follows from the oddness and Lipschitz property of $\phi\ss{o}$:
\begin{equation}
    \norm{\mathbb{E}[\phi\ss{o}^2(\mathbf{z}^Q_L)]}_\infty = \norm{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) - \phi\ss{o}(\mathbf{0}))^2]}_\infty
    \le \norm{\mathbb{E}[(\mathbf{z}^Q_L)^2]}_\infty.
\end{equation}
Likewise, $\norm{\mathbb{E}[\phi^2(\mathbf{z}^P_L)]}_\infty \le \norm{\mathbb{E}[(\mathbf{z}^P_L)^2]}_\infty$. We can upper  by applying  \cref{lem:z-squared-recursion} to each of the two terms:
\begin{align}
    \norm{\mathbb{E}_{\ensuremath{Q}}[(\mathbf{z}_L)^2]}_\infty \leq \left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) - \alpha^2
\end{align} 
and
\begin{align}
    \norm{\mathbb{E}_{\ensuremath{P}}[(\mathbf{z}_L)^2]}_\infty \leq \gamma_{\alpha,M}^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) -\alpha^2.
\end{align}
Therefore, the first term in \cref{eqn:phi2Q_phi2P} is upper bounded by
\begin{align}
    \norm{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) + \phi\ss{o}(\mathbf{z}^P_L))^2]}_\infty 
    &\le 2 \gamma_{\alpha,M}^L ((K^2 \lor 1)^L + 1 ) (\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2 ) - 4\alpha^2 \\
    &\le 4 \gamma_{\alpha,M}^L (K^2 \lor 1)^L (\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2 ), \label{eqn:diag-frob-norm-part1}
\end{align}
where we use that $(K^2 \lor 1)^L + 1 \le 2(K^2 \lor 1)$ and drop the $-4\alpha^2$ term for simplicity later on.

\paragraph{Bounding $\mathbb{E}[ \norm{\mathbf{z}^Q_L - \mathbf{z}^P_L}^2_2]$}

It remains to upper bound the second term in \cref{eqn:phi2Q_phi2P}. To do so, we will setup a linear, non-homogenous recursion relation. To start, notice for $2 \leq \ell \le L$, by adding and subtracting $\mathbfcal{E}\phi\ss{o}(\mathbf{z}^Q_{\ell-1})$ and then applying the triangle inequality, we have
\begin{equation}
    \begin{split}
    \norm{\mathbf{z}^Q_\ell - \mathbf{z}^P_\ell}_2 
    \le & \tfrac1{\sqrt{M}}\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}_2 \norm{\phi\ss{o}(\mathbf{z}^Q_{\ell-1})}_2 
    + \alpha\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}_2 \\
    & + \tfrac1{\sqrt{M}}\norm{ \mathbfcal{E}}_2 \norm{\phi\ss{o}( \mathbf{z}^Q_{\ell-1}) - \phi\ss{o}(\mathbf{z}^P_{\ell-1})}_2 
    + \norm{\mathbf{s}^Q_\ell \circ \bm{\upvarepsilon} + \mathbf{m}^Q_\ell - \bm{\upvarepsilon}}_2, \label{eqn:zq_minus_zp} 
    \end{split}
\end{equation}
where we note that $\norm{\mathbf{1}}_2=\sqrt{M}$ cancels the $\tfrac{1}{\sqrt{M}}$ term in the second term. 
To obtain a tighter bound, we consider the cases of $\alpha=0$ and $\alpha\neq0$ separately by defining $c_\alpha = 3$ if $\alpha=0$ and $c_\alpha = 4$ if $\alpha\neq0$. Then, for any $a_1, a_2, a_3, a_4 \in \mathbb{R}$, we have $(a_1 + a_2 + a_3 + \alpha a_4)^2 \le c_\alpha(a_1^2 + a_2^2 + a_3^2 + \alpha^2 a_4^2)$. Applying this expression to \cref{eqn:zq_minus_zp}, squaring both sides, and then taking the expectation we have
\begin{equation}
    \begin{split}
    \mathbb{E}[\norm{\mathbf{z}^Q_\ell - \mathbf{z}^P_\ell}_2^2]
    \le & \tfrac{c_\alpha}{M}\mathbb{E}[\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}_2^2] \mathbb{E}[\norm{\phi\ss{o}(\mathbf{z}^Q_{\ell-1})}_2^2]
    + c_\alpha \alpha^2\mathbb{E}[\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}_2^2] \\
    & + \tfrac{c_\alpha}{M}\mathbb{E}[\norm{ \mathbfcal{E}}_2^2] \mathbb{E}[\norm{\phi\ss{o}( \mathbf{z}^Q_{\ell-1}) - \phi\ss{o}(\mathbf{z}^P_{\ell-1})}_2^2] 
    + c_\alpha \mathbb{E}[\norm{\mathbf{s}^Q_\ell \circ \bm{\upvarepsilon} + \mathbf{m}^Q_\ell - \bm{\upvarepsilon}}_2^2].\label{eqn:E_zq_minus_zp} 
    \end{split}
\end{equation}
We now turn to bounding each of the terms in \cref{eqn:E_zq_minus_zp}. First, by \cref{lem:expectation_squared_bound_update},
\begin{equation}
\tfrac{1}{M}\mathbb{E}[\norm{\mathbfcal{E}}_2^2] \le \eta_M.
\end{equation}
Next, we have
\begin{align}
\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}_2 &\leq \norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}\ss{F} \\
&\leq \norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E}- \mathbfcal{E}}\ss{F} + \norm{\mathbf{M}^Q_\ell}\ss{F} \\
\implies \mathbb{E}[\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}_2^2] &\leq 2\mathbb{E}[\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E}- \mathbfcal{E}}\ss{F}^2 + 2\mathbb{E}[\norm{\mathbf{M}^Q_\ell}\ss{F}^2].
\end{align}
We can then bound each term by $\operatorname{KL}(\ensuremath{Q},\ensuremath{P})$. To do this, first notice we can write
\begin{align}
\mathbb{E}[\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E}- \mathbfcal{E}}\ss{F}^2] = \mathbb{E}\left[\sum_m \sum_{m'} (\bm{\upsigma}^Q_\ell-1)^2\epsilon_{m,m'}^2\right] = \sum_m \sum_{m'} (\bm{\upsigma}^Q_\ell-1)^2\mathbb{E}\left[\epsilon_{m,m'}^2\right] = \sum_m \sum_{m'} (\bm{\upsigma}^Q_\ell-1)^2. \label{eqn:mat-norm-bound}
\end{align}
By an application of \cref{lem:parameter_bound}, we then have,
\begin{align}
\mathbb{E}[\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E}- \mathbfcal{E}}\ss{F}^2] \leq K^2 \;\; \text{and} \;\; \mathbb{E}[\norm{ \mathbf{M}^Q_\ell }\ss{F}^2] \leq K^2, \label{eqn:first-terms-bound}
\end{align}
where, as before, $K = \sqrt{2\operatorname{KL}(\ensuremath{Q},\ensuremath{P})}$. Therefore, we obtain
\begin{align*}
    \mathbb{E}[\norm{\mathbf{S}^Q_\ell \circ \mathbfcal{E} + \mathbf{M}^Q_\ell - \mathbfcal{E}}_2^2] \leq  4K^2.
\end{align*}
We can apply an identical argument to $\norm{\mathbf{s}^Q_\ell \circ \bm{\upvarepsilon} + \mathbf{m}^Q_\ell - \bm{\upvarepsilon}}_2$ to conclude that 
\begin{align}
\mathbb{E}[\norm{\mathbf{s}^Q_\ell \circ \bm{\upvarepsilon} + \mathbf{m}^Q_\ell - \bm{\upvarepsilon}}_2^2] \le  4K^2.
\end{align}
Finally, we have that
\begin{align}
    \mathbb{E}[\norm{\phi\ss{o}(\mathbf{z}^Q_{\ell-1})}_2^2] 
    = \mathbb{E}\left[\sum_{m=1}^M \phi\ss{o}^2(z^Q_{\ell-1,m}) \right]
    = \sum_{m=1}^M \mathbb{E}[\phi\ss{o}^2(z^Q_{\ell-1,m}) ]
    \le M \norm{\mathbb{E}[\phi\ss{o}^2(\mathbf{z}^Q_{\ell-1})]}_\infty 
    \le M \norm{\mathbb{E}[(\mathbf{z}^Q_{\ell-1})^2]}_\infty,
\end{align}
where the last inequality follows from the oddness and Lipschitzness of $\phi\ss{o}$. Dividing by $M$ and applying \cref{lem:z-squared-recursion} to the last expression, we can conclude that
\begin{align}
    \tfrac1{M}\mathbb{E}[\norm{\phi\ss{o}(\mathbf{z}^Q_{\ell-1})}_2^2] \le \left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{\ell - 1}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) - \alpha^2.
\end{align}
We now plug these expressions into \cref{eqn:zq_minus_zp}, noting the cancellation of $\alpha^2$ terms, to obtain
\begin{equation}
    \mathbb{E}[\norm{\mathbf{z}^Q_\ell - \mathbf{z}^P_\ell}_2^2] \le 
    4c_\alpha K^2 \left( \left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{\ell - 1}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) + 1 \right) + c_\alpha \eta_M \, \mathbb{E}[\norm{\mathbf{z}^Q_{\ell-1} - \mathbf{z}^P_{\ell-1}}_2^2].\label{eqn:diagonal-recursion}
\end{equation}

We now set up the recursion, with base case
\begin{align}
    \mathbb{E}[\norm{\mathbf{z}^Q_1 - \mathbf{z}^P_1}_2^2] &\leq  4c_\alpha K^2 \left(\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right)+1\right). \label{eqn:diagonal-base}
\end{align}
Taken together, \cref{eqn:diagonal-recursion} and \cref{eqn:diagonal-base} define a linear, non-homogeneous recursion in $\mathbb{E}[\norm{\mathbf{z}^Q_l - \mathbf{z}^P_l}_2^2]$ with variable coefficients.
By unrolling the recursion, we find that\footnote{
    Suppose that $x_n \le b_n + a x_{n-1}$ for $n \ge 2$ and $x_1 \le b_1$.
    We then show that $x_n \le \sum_{n'=1}^n a^{n - n'} b_n$ for all $n \ge 1$.
    For the base case, note that the case $n=1$ is true because $x_1 \le b_1$
    For the induction step, suppose that the case $n \in \mathbb{N}$ is true.
    Then $
        x_{n+1}
        \le b_{n + 1} + a \sum_{n'=1}^n a^{n - n'} b_n
        \le a^{n + 1 - (n+1)} b_{n + 1} + \sum_{n'=1}^n a^{n + 1 - n'} b_n
        =\sum_{n'=1}^{n + 1} a^{n + 1 - n'} b_n
    $, so the case $n + 1$ is also true.
    We conclude that $x_n \le \sum_{n'=1}^n a^{n - n'} b_n$ for all $n \ge 1.$
}
\begin{align}
    \mathbb{E}[\norm{\mathbf{z}^Q_{L} - \mathbf{z}^P_{L}}_2^2] 
    &\le \sum_{\ell=1}^{L} (c_\alpha \eta_M)^{L - \ell} \left(4 c_\alpha K^2 \left(\left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{\ell - 1}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right)+1\right)\right) \\
    &\le (c_\alpha \eta_M \lor \gamma_{\alpha,M})^{L - 1} 4 c_\alpha K^2 \sum_{\ell=1}^{L} (K^2 \lor 1)^{\ell - 1}\left( \alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2+1\right),
\end{align}
where in the second inequality we factor out $(\gamma_{\alpha,M}(K^2 \lor 1))^{\ell - 1}$ (which is possible since it is greater than 1) and then combine $(4c)^{L-\ell} \gamma_{\alpha,M}^{\ell -1} \le (4c \lor \gamma_{\alpha,M})^{L - 1}$. We can bound the sum by $L$ times the largest term in the sum, which is the $l=L$ term since $K^2 \lor 1 \ge 1$:
\begin{align}
    \mathbb{E}[\norm{\mathbf{z}^Q_{L} - \mathbf{z}^P_{L}}_2^2] 
    &\le L \left[ (c_\alpha \eta_M \lor \gamma_{\alpha,M})^{L - 1} 4 c_\alpha K^2 (K^2 \lor 1)^{L - 1} \left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2+1\right) \right] \\
    &\le 32 (c_\alpha \eta_M \lor \gamma_{\alpha,M})^{L - 1} L K^2 (K^2 \lor 1)^{L - 1} \left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right)
\end{align}
where the second inequality uses that $1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2 + 1 \le 2 (1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2)$ and $c_\alpha \le 4$. 











Define $\rho_{\alpha,M} = c_\alpha \eta_M \lor \gamma_{\alpha, M}$. Recall from \cref{lem:expectation_squared_bound_update} that $\eta_{M} \in (5, 19)$ depends on if $M \ge 36$. Recall also from \cref{lem:z-squared-recursion} that $\gamma_{\alpha, M} \in (17, 97)$ depends if $M \ge 36$ and if $\alpha=0$. Comparing cases, we see
\begin{equation}
    \rho_{\alpha, M} =
    \begin{cases}
    12(2+\sqrt{2\pi}) \in (54,55) & \alpha=0, M<36 \\
    \tfrac23(13+2\sqrt{43}) \in (17,18) & \alpha=0, M\ge 36 \\
    28 + \sqrt{793} \in (56,57) & \alpha\neq 0, M<36 \\
    48 + \sqrt{2353} \in (96,97) & \alpha\neq 0, M\ge 36. \\
    \end{cases}
\end{equation}
Notice $\rho_{\alpha, M}$ is equal to $\gamma_{\alpha, M}$ except in the case of $\alpha=0$ and $M<36$.
\begin{equation}
    \mathbb{E}[\norm{\mathbf{z}^Q_{L} - \mathbf{z}^P_{L}}_2^2] 
    \le 32 \rho_{\alpha, M}^{L - 1} L K^2 (K^2 \lor 1)^{L - 1} \left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right). \label{eqn:diag-frob-norm-part2}
\end{equation}

\paragraph{Combining terms.}
Plugging Equations (\ref{eqn:diag-frob-norm-part1}) and (\ref{eqn:diag-frob-norm-part2}) into \cref{eqn:phi2Q_phi2P} and simplifying we have
\begin{align}
    \|\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})^2 ]- \mathbb{E}_{\ensuremath{P}}[\phi\ss{o}(\mathbf{z}_{L})^2]\|_2
    &\le 8 \sqrt{2} \rho_{\alpha, M}^{L-\tfrac12} L^{1/2} K (K^2 \lor 1)^{L-\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right).
\end{align}

We have



\begin{align}
    |D^{i}_{\ensuremath{Q}}- D^{i}_{\ensuremath{P}}| &= \frac{1}{M}\left\lvert\mathrm{tr}\parens*{
        \parens*{\mathbf{\Sigma}_Q- \mathbf{I}}\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]
            + (\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]-\mathbb{E}_{\ensuremath{P}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}])
    }
    \right\rvert
    \\
    &\le \tfrac{1}{M}\left\lvert\mathrm{tr}\parens*{
        \parens*{\mathbf{\Sigma}_Q- \mathbf{I}}\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]
        } \right\rvert
        + \tfrac{1}{M}\left\lvert\mathrm{tr}\parens*{\mathbb{E}_{\ensuremath{Q}}[\phi(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]-\mathbb{E}_{\ensuremath{P}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]}\right\rvert \label{eq:diag_trace_term}
\end{align}
Next we bound each of the two terms in \cref{eq:diag_trace_term} separately, starting with the first term. First, note that $\mathbf{\Sigma}_Q - \mathbf{I}$ is a diagonal matrix and let $\bm{\upsigma}^2 = \operatorname{diag}(\mathbf{\Sigma}_Q)$. Since the trace of a matrix product is the element-wise inner product of the matrices, the first term in \cref{eq:diag_trace_term} becomes
\begin{align}
    \left\lvert\mathrm{tr}\parens*{
        \parens*{\mathbf{\Sigma}_Q- \mathbf{I}}\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]} \right\rvert
    &= \left\lvert\langle \bm{\upsigma}_Q^2 - \mathbf{1}, \mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}^2(\mathbf{z}_{L})]]\rangle \right\rvert
    \\
    &\leq \|\bm{\upsigma}_Q^2 - \mathbf{1}\|_1\|\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}^2(\mathbf{z}_{L}) ] \|_\infty 
    \\
    &\leq \sqrt{M} \|\bm{\upsigma}_Q^2 - \mathbf{1}\|_2 \|\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}^2(\mathbf{z}_{L})]\|_\infty
\end{align}






where the first inequality is an application of H\"{o}lder's inequality. Now $\|\bm{\upsigma}_Q^2 -\mathbf{1}\|_{2} \leq \left (2 + K\right)K$ by \cref{lem:parameter_bound} (iv.), where $K = \sqrt{2\operatorname{KL}(\ensuremath{Q},\ensuremath{P})}$. To upper bound $\norm{\mathbb{E}_Q[\phi^2(\mathbf{z}_L)]}_\infty$, notice we can use the oddness and Lipschitz property of $\phi\ss{o}$ to write
    \begin{equation}
        \norm{\mathbb{E}[\phi\ss{o}^2(\mathbf{z}^Q_L)]}_\infty = \norm{\mathbb{E}[(\phi\ss{o}(\mathbf{z}^Q_L) - \phi\ss{o}(\mathbf{0}))^2]}_\infty
        \le \norm{\mathbb{E}[(\mathbf{z}^Q_L)^2]}_\infty.
    \end{equation}
    We can upper bound this using \cref{lem:z-squared-recursion}:
    \begin{align}
        \norm{\mathbb{E}_{\ensuremath{Q}}[(\mathbf{z}_L)^2]}_\infty \leq \left(\gamma_\alpha(K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right).
    \end{align} 
Therefore, the first term in \cref{eq:diag_trace_term} is upper bounded by
\begin{align}
    \left\lvert\mathrm{tr}\parens*{
        \parens*{\mathbf{\Sigma}_Q- \mathbf{I}}\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]} \right\rvert
    &\le \sqrt{M}
        \left(2 + K\right)K
        \left(\gamma_\alpha(K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) \\
    &\le \sqrt{M}
        \gamma_\alpha^{L} K \left(K^2 \lor 1\right)^{L+\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right),
\end{align}
where we use that $K + 2 \le 3 (K^2 \lor 1)^{1/2}$ in the second inequality. 

The second term in \cref{eq:diag_trace_term} can be upper bounded by
\begin{align}
    \left\lvert \mathrm{tr}\parens*{\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]-\mathbb{E}_{\ensuremath{P}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]} \right\rvert 
    &= \left\lvert \langle \mathbf{1}, \mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}^2(\mathbf{z}_{L}) ] - \mathbb{E}_{\ensuremath{P}}[\phi\ss{o}^2(\mathbf{z}_{L}) ] \rangle \right\rvert
    \\
    &\le \norm{\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}^2(\mathbf{z}_{L}) ] - \mathbb{E}_{\ensuremath{P}}[\phi\ss{o}^2(\mathbf{z}_{L}) ]}_1
    \\
    &\le \sqrt{M} \norm{\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}^2(\mathbf{z}_{L}) ] - \mathbb{E}_{\ensuremath{P}}[\phi\ss{o}^2(\mathbf{z}_{L}) ]}_2
    \\
    &\le \sqrt{M} 8 \sqrt{2} \rho_{\alpha, M}^{L-\tfrac12} L^{1/2} K (K^2 \lor 1)^{L-\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right)
\end{align}
where the last inequality follows from \cref{lem:diag-frob-norm}. 

Plugging the bounds on both terms into \cref{eq:diag_trace_term} and simplifying we have
\begin{align}
    |D^{i}_{\ensuremath{Q}}(\mathbf{x}) - D^{i}_{\ensuremath{P}}(\mathbf{x})| 
    &\leq  
    \tfrac{1+8\sqrt{2}}{\sqrt{M}} 
    \rho_{\alpha, M}^{L} L^{1/2} K (K^2 \lor 1)^{L+\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) \\
    &\leq  
    \tfrac{16 + \sqrt{2}}{\sqrt{M}} 
    \rho_{\alpha, M}^{L} L^{1/2} \operatorname{KL}(\ensuremath{Q},P)^{1/2} (2 \operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \lor 1)^{L+\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right)
\end{align}
where we use $1\le L^{1/2}$, $\rho_{\alpha, M}^{L-\tfrac12}\le \rho_{\alpha, M}^L$, $\gamma_{\alpha,M} \le \rho_{\alpha,M}$,
and $(K^2 \lor 1)^{L-\tfrac12} \le (K^2 \lor 1)^{L+\tfrac12}$ to more simply group the terms.

\begin{align}
    |D^{i}_{\ensuremath{Q}}(\mathbf{x}) - D^{i}_{\ensuremath{P}}(\mathbf{x})| 
    &\leq  
    \tfrac{1+8\sqrt{2}}{\sqrt{M}} 
    \rho_{\alpha, M}^{L} L^{1/2} K (K^2 \lor 1)^{L+\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) \\
    &\leq  
    \tfrac{16 + \sqrt{2}}{\sqrt{M}} 
    \rho_{\alpha, M}^{L} L^{1/2} \operatorname{KL}(\ensuremath{Q},P)^{1/2} (2 \operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \lor 1)^{L+\tfrac12}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right)
\end{align}

By \cref{rem:outer_offset}, 
\begin{align}
      \  \|\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L}(\mathbf{x}))\phi\ss{o}(\mathbf{z}_{L}(\mathbf{x}))^{\text{\textsf{T}}}]\|_2 &\leq  12\sqrt{M}\left(
                \norm{\mathbb{E}[\mathbf{z}_L^2]}_\infty
                + K^2 \left((\alpha^2 + \norm{\mathbb{E}[\mathbf{z}_{L-1}^2]}_\infty) \lor 1 \right) \right). \label{eqn:apply_outer_offset}
\end{align}
Note that in the $\alpha=0$ case we could save a factor of 2 by instead applying \cref{lem:outer}, but for simplicity we consider any $\alpha\in\mathbb{R}$ here. We could also reduce the constant by separately considering the case of $M \ge 3$ but we do not for simplicity. 
We now upper bound each of the two terms above. By \cref{lem:z-squared-recursion},
\begin{equation}
    \alpha^2 + \norm{\mathbb{E}[(\mathbf{z}_L)^2]}_\infty \leq \left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right). \label{eqn:z2_L}
\end{equation}
Similarly,
\begin{align}
    K^2 \left((\alpha^2 + \norm{\mathbb{E}[\mathbf{z}_{L-1}^2]}_\infty) \lor 1 \right)
    &\leq K^2 \left(\left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{L-1}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) \lor 1\right) \\
    &\leq (K^2 \lor 1) \left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{L-1}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) \\
    &\leq \left(\gamma_{\alpha,M}(K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right),
\end{align}
where we use that $\gamma_{\alpha,M}\ge1$ in the last two inequalities. Adding the two terms together in \cref{eqn:apply_outer_offset}, noting that we drop the $\alpha^2$ term in the \cref{eqn:z2_L} to more simply group the terms, we have
\begin{equation}
    \\|\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L}(\mathbf{x}))\phi\ss{o}(\mathbf{z}_{L}(\mathbf{x}))^{\text{\textsf{T}}}]\|_2 
    \leq 24\sqrt{M} \left(\gamma_{\alpha,M} (K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right).
\end{equation}

We have 
\begin{align}
    |O^i_{\ensuremath{Q}}(\mathbf{x})| = \frac{1}{M}|\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]^{\text{\textsf{T}}}\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]|
    \leq \frac{1}{M}\|\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]\|_2^2\norm{\mathbb{E}_{\ensuremath{Q}}[\phi\ss{o}(\mathbf{z}_{L})\phi\ss{o}(\mathbf{z}_{L})^{\text{\textsf{T}}}]}_2,
\end{align}
by the definition of the operator norm. \Cref{lem:parameter_bound} tells us that $\|\mathbb{E}_{\ensuremath{Q}}[\mathbf{w}_{L+1}]\|_2^2 \leq K^2 = 2\operatorname{KL}(\ensuremath{Q},\ensuremath{P})$. Combining this estimate with \cref{lem:offdiag-operator-norm} gives
\begin{align}
    |O^i_{\ensuremath{Q}}(\mathbf{x})| 
    &\leq \tfrac{1}{M} \left(K^2\right) \left(24 \sqrt{M} \left(\gamma_{\alpha,M} (K^2 \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right) \right)\\
    &\leq \tfrac{48}{\sqrt{M}}
    \operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \left(\gamma_{\alpha,M} (2\operatorname{KL}(\ensuremath{Q},\ensuremath{P}) \lor 1)\right)^{L}\left(\alpha^2 + 1\lor \tfrac1{D\ss{i}}\|\mathbf{x}\|^2_2\right).
\end{align}

\begin{align}
    \!\!\!\operatorname{KL}(Q^*, P) &\leq \mathbb{E}_{\bm{\uptheta}\sim Q^*}[\log \mathcal{L}(\bm{\uptheta})] -\mathbb{E}_{\bm{\uptheta}\sim P}[\log \mathcal{L}(\bm{\uptheta})]\\
    & \leq \!CN \!-\! \mathbb{E}_{\bm{\uptheta}\sim P}[\textstyle\sum_{n=1}^N \!\log p(\mathbf{y}_n | \mathbf{f}_{\bm{\uptheta}}(\mathbf{x}_n))] \\
    & \leq \! CN \!-\! \mathbb{E}_{\bm{\uptheta} \sim \ensuremath{P}}[\textstyle\sum_{n=1}^N h_n(\mathbf{f}_{\bm{\uptheta}}(\mathbf{x}_n))]
\end{align}

Consider a Gaussian likelihood so that,
\begin{equation}
    \log p(y_n | f(\mathbf{x}_n)) = -\log 2 \pi \sigma^2 - \tfrac{1}{2\sigma^2}(y-f(\mathbf{x}_n))^2.
\end{equation}
We then have $\log p(y_n | f(\mathbf{x}_n)) \leq -\log 2 \pi \sigma^2=:C$. Also, 
\begin{align}
    \mathbb{E}_{\ensuremath{P}}[\log p(y_n | f(\mathbf{x}_n))] = CN - \frac{\sum_{n=1}^N y_n^2+\mathbb{V}[f(\mathbf{x}_n)]}{2\sigma^2}
\end{align}
Hence by \cref{eqn:var-prior-bound},
\begin{align}
     \operatorname{KL}(Q^*, P) \leq \frac{(L+1)N+ \sum_{n=1}^{N} y_n^2 + \|\mathbf{x}_n\|^2_2 }{2\sigma^2}. \label{eqn:kl-upper-bound-gaussian}
\end{align}

For a Student $t$ likelihood (used in robust regression) with $\nu >0$ degrees of freedom, we have
\begin{equation}
    \log p(y_n
    |f(\mathbf{x}_n)) = c(\nu) - \frac{\nu+1}{2} \log \parens*{1+\frac{(f(\mathbf{x}_n)-y_n)^2}{\nu}}.
\end{equation}
As the second term is non-negative, this is upper bounded by $c(\nu)$. 
Applying $\log (1+a) \leq a$, we have
\begin{equation}
    \log p(y_n
    |f(\mathbf{x}_n)) \geq c(\nu) - \frac{\nu+1}{2}\frac{ (f(x_n)-y_n)^2}{\nu}
\end{equation}
which provides the desired quadratic lower bound.

For a logistic likelihood, we have
\begin{equation}
    \log p(y_n
    |f(\mathbf{x}_n)) = y_n\log\parens*{\frac{1}{1+e^{-f(\mathbf{x}_n)}}} + (1-y_n)
   \log\left(\frac{e^{-f(\mathbf{x}_n)}}{1+e^{-f(\mathbf{x}_n)}}\right)
\end{equation}
As both terms are non-positive, we have $        \log p(y_n
    |f(\mathbf{x}_n))\leq 0$. 
As $g(a)=\log(1+e^{-a})$ is three times differentiable, we have that for any $a \in \mathbb{R}$, there exists a $\xi_a \in \mathbb{R}$ such that,
\begin{equation}
    \log(1+e^{-a}) = \log 2 - \frac{a}{2} + \frac{a^2}{8} + \frac{g^{(3)}(\xi_a)}{3!}a^3.
\end{equation}
As $\mathrm{sign}(g^{(3)}(\xi_a)) = \mathrm{sign}(\xi_a) =\mathrm{sign}(a) = \mathrm{sign}(a^3)$, the final term is non-negative, so
\begin{equation}
    \log(1+e^{-a}) \leq \log 2 - \frac{a}{2} + \frac{a^2}{8}.
\end{equation}
Hence
\begin{align}
    \log p(y_n=1
    |f(\mathbf{x}_n)) &\geq -\log 2 + \frac{f(\mathbf{x}_n) }{2}-\frac{f(\mathbf{x}_n) ^2}{8} \text{ and} \\
    \log p(y_n=0
    |f(\mathbf{x}_n)) &=     \log p(y_n=1
    |f(\mathbf{x}_n))-f(\mathbf{x}_n) \geq -\log 2 -\frac{f(\mathbf{x}_n) }{2}-\frac{f(\mathbf{x}_n) ^2}{8}.
\end{align}

Consider $N$ one-dimensional data points $(\mathbf{x}_n, y_n)_{n=1}^N$ ($D\ss{i}\in \mathbb{N}$ and $D\ss{o}=1$) and let $\overline{y}$ be the average of the observed values.
Let $Q^*$ be the optimal mean-field variational posterior for a neural network with $L$ hidden layers and $M$ neurons per hidden layer.
Suppose $\phi\ss{e}=\alpha$ for some $\alpha \in \mathbb{R}$ and $\phi\colon \mathbb{R} \to \mathbb{R}$ is $1$-Lipschitz.
Also suppose that the likelihood is Gaussian with variance parameter $\sigma^2$.
Then, along any finite-dimensional distribution, as $M \to \infty$, $f \sim Q^*$ converges weakly to the sum of the NNGP and an independent Gaussian with distribution 
\begin{equation}
    \mathcal{N}\parens*{ \parens*{\beta \times 1 + (1 - \beta) \times \frac{1}{1 + \alpha^2 + \frac{\sigma^2}{N}}} \overline{y}, \frac{\sigma^2}{\sigma^2 + N}}
    \quad \text{where} \quad
    \beta = \frac{\alpha^2}{\alpha^2 + \frac{\sigma^2}{N}}.
\end{equation}

The proof conceptually proceeds in two steps.
In the first conceptual step, we show that the parameters of all layers but the last layer converge to the prior.
Intuitively, this means that the overall solution converges to mean-field inference in the Bayesian linear regression model with features $x \mapsto \mathbb{E}[\phi(z_{L,m})(x)]$.
In the second conceptual step, we show that this mean-field solution of the Bayesian linear regression model converges to the prior, thereby completing the proof.
Whereas conceptually the proof proceeds in two steps, below we split up these two steps into six steps, as follows:
\begin{enumerate}[leftmargin=5em]
    \item[Step 1:] We prove that the parameters of the hidden layers converge to the prior.
    \item[Step 2:] By assuming two claims, Claim 1 and Claim 2, we almost conclude the proof. It only remains to compute the limiting distribution of the final bias.
    \item[Step 3:] We prove Claim 1.
    \item[Step 4:] Using Claim 1, we compute the limiting distribution of the final bias.
    \item[Step 5:] Using Claim 1 and the limiting distribution of the final bias, we prove Claim 2.
    \item[Step 6:] We reconcile Step 2 with the limiting distribution of the bias to finally conclude the proof.
\end{enumerate}

Throughout the proof and unlike in the theorem statement, we do \emph{not} incorporate $\alpha$ in $\phi$, but write $\phi_\alpha = \phi + \alpha$ for the version of $\phi$ that does include $\alpha$.
Moreover, we write $\bm{\uptheta}_{L+1}$ for the parameters of the final layer and let $\bm{\uptheta}_{1:L}$ be all remaining parameters, so $\bm{\uptheta} = (\bm{\uptheta}_{L+1}, \bm{\uptheta}_{1:L})$.
We decompose the parameters of the final layer as $\bm{\uptheta}_{L+1} = (\mathbf{w}_{L+1}, b_{L+1})$, so also $\bm{\uptheta} = (\mathbf{w}_{L+1}, b_{L+1}, \bm{\uptheta}_{1:L})$.

We will consider the limits $M \to \infty$ and $\operatorname{KL} \to 0$.
Using results from earlier sections in the appendix, we establish the following bounds which ignore proportionality constants irrelevant for the limits $M \to \infty$ and $\operatorname{KL} \to 0$:
\begin{align}
    \norm{\mathbb{E}_Q[\phi(\mathbf{z}_{L+1})]}_2
    \overset{\text{(\cref{lem:last-layer-bound})}}&{\lesssim}\!\!\!\!\! \sqrt{\operatorname{KL}(Q_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}})},
    \label{eq:dist:phi}
    \\

    \abs{\mathbb{E}_Q[\tfrac{1}{\sqrt{M}} \lra{\mathbf{w}_{L+1}, \phi(\mathbf{z}_{L+1})}]}
    \overset{\text{(\cref{thm:app-convergence-of-mean})}}&{\lesssim}\!\!\!\!\! \tfrac{1}{\sqrt{M}} \operatorname{KL}(Q_{\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L}}, P_{\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L}}),
    \label{eq:dist:mean}
    \\

    \abs{\mathbb{E}_Q[b_{L+1}]} \overset{\text{(\cref{lem:parameter_bound})}}&{\lesssim} \sqrt{\operatorname{KL}(Q_{b_{L+1}}, P_{b_{L+1}})},
    \label{eq:dist:bias}
    \\

    \tfrac1M \norm{\mathbb{E}_{Q}[\phi(\mathbf{z}_L)\phi(\mathbf{z}_L)^{\text{\textsf{T}}}]}_2
    \overset{\text{(\cref{lem:offdiag-operator-norm})}}&{\lesssim}
    \tfrac{1}{\sqrt{M}},
    \label{eq:dist:outer}
    \\

    \norm{\mathbb{E}_Q[\phi_\alpha(\mathbf{z}_L)^2]}_\infty
    \overset{\text{(\cref{lem:z-squared-recursion})}}&{\lesssim}
    1,
    \label{eq:dist:square}
    \\

    \abs{\mathbb{E}_{Q}[\phi(z_{L,m})\phi(z_{L,m'})]}
    \overset{\text{(\cref{lem:cov,lem:z-squared-recursion}, $m \neq m'$)}}&{\lesssim}
    \sqrt{\operatorname{KL}(Q_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}})},
    \label{eq:dist:cov}
    \\

    \!\!\!\!\!\!\!\!\tfrac1M\abs{\operatorname{tr} \left( \mathbb{E}_{Q}[\mathbf{w}_{L+1} \mathbf{w}_{L+1}^{\text{\textsf{T}}}] (
        \mathbb{E}_{Q}[\phi(\mathbf{z}_L) \phi(\mathbf{z}_L)^{\text{\textsf{T}}}]
        \!-\! \mathbb{E}_{P}[\phi(\mathbf{z}_L) \phi(\mathbf{z}_L)^{\text{\textsf{T}}}]
    ) \right)}
    \overset{\text{(\cref{lem:second_moment_conditional_prior})}}&{\lesssim} \tfrac{1}{\sqrt{M}} \sqrt{\operatorname{KL}(Q_{\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L}},\! P_{\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L}})},
    \label{eq:dist:complicated_trace}
    \\

    \tfrac1{M}\abs{\mathbb{E}[\lra{\mathbf{w}_{L+1}, \alpha \mathbf{1}} \lra{\mathbf{w}_{L+1}, \phi(\mathbf{z}_L)}]}
    \overset{\text{(\cref{lem:inner_prod})}}&{\lesssim}
    \tfrac{1}{\sqrt{M}} \sqrt{\operatorname{KL}(Q_{\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L}}, P_{\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L}})}.
    \label{eq:dist:complicated_inner_prod}
\end{align}
Recall that any KL divergence between parameters of an optimal variational posterior and the prior is bounded uniformly over $M$ (\cref{app:kl-bounds}).
This means, e.g., that the mean of any weight of any variational posterior can be considered as an unknown but bounded constant (\cref{app:parameter-bounds}).

\textbf{Step 1 (convergence of hidden layers).}
Let $P$ be the prior and let $Q^*$ be the optimal mean-field posterior.
Decompose the KL divergence as follows:
\begin{equation}
    \operatorname{KL}(Q^*, P)
    = \operatorname{KL}(Q^*_{\bm{\uptheta}_{L+1}}, P_{\bm{\uptheta}_{L+1}}) + \operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}})
    = \mathbb{E}_{Q^*}[\log p(\mathbf{y} \,|\, \bm{\uptheta})] - \operatorname{ELBO}(Q^*).
\end{equation}
Let $Q'$ be the modification of $Q^*$ where the distribution of $\bm{\uptheta}_{1:L}$ is set to the prior.
Then
\begin{align}
    \operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}})
    &=
        \mathbb{E}_{Q^*}[\log p(\mathbf{y} \,|\, \bm{\uptheta})]
        - \operatorname{ELBO}(Q^*)
        - \operatorname{KL}(Q^*_{\bm{\uptheta}_{L+1}}, P_{\bm{\uptheta}_{L+1}}) \\
    &=
        \mathbb{E}_{Q^*}[\log p(\mathbf{y} \,|\, \bm{\uptheta})]
        - \operatorname{ELBO}(Q^*)
        + \operatorname{ELBO}(Q')
        - \mathbb{E}_{Q'}[\log p(\mathbf{y} \,|\, \bm{\uptheta})].
\end{align}
Therefore, by optimality of $Q^*$,
\begin{align}
    &\operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}}) \nonumber \\
    &\quad\le\vphantom{\sum^N_{n}} \mathbb{E}_{Q^*}[\log p(\mathbf{y} \,|\, \bm{\uptheta})] - \mathbb{E}_{Q'}[\log p(\mathbf{y} \,|\, \bm{\uptheta})] \\
    &\quad= -\frac1{2\sigma^2}\sum_{n=1}^N(
        \mathbb{E}_{Q^*}[(y_n - f(\mathbf{x}_n))^2]
        - \mathbb{E}_{Q'}[(y_n - f(\mathbf{x}_n))^2]
    ) \\
    &\quad= -\frac1{2\sigma^2}\sum_{n=1}^N(
        \mathbb{E}_{Q^*}[f^2(\mathbf{x}_n) - 2 y_n f(\mathbf{x}_n) ]
        - \mathbb{E}_{Q^*}[\mathbb{E}_{P}[f^2(\mathbf{x}_n) - 2 y_n f(\mathbf{x}_n) \,|\, \bm{\uptheta}_{L+1}]]
    ) \\
    &\quad\le \frac1{2\sigma^2}\sum_{n=1}^N\Big(
        \abs{\mathbb{E}_{Q^*}[f^2(\mathbf{x}_n) -\mathbb{E}_{P}[f^2(\mathbf{x}_n)\,|\, \bm{\uptheta}_{L+1}]]}
        + 2 \abs{y_n} \abs{\mathbb{E}_{Q^*}[f(\mathbf{x}_n) -\mathbb{E}_{P}[f(\mathbf{x}_n)\,|\, \bm{\uptheta}_{L+1}]]}
    \Big).
\end{align}
Define $\tilde b = \tfrac1{\sqrt{M}}\lra{\mathbf{w}_{L+1}, \alpha \mathbf{1}} + b_{L+1}$
and let $\tilde f(\mathbf{x}_n) = f(\mathbf{x}_n) - \tilde b$.
Note that $\tilde b$ is $\sigma(\bm{\uptheta}_{L+1})$-measurable (i.e.~$\tilde b$ is deterministic after conditioning on the top layer parameters).
Rearrange as
\begin{align}
    &\mathbb{E}_{Q^*}[f^2(\mathbf{x}_n) -\mathbb{E}_{P}[f^2(\mathbf{x}_n)\,|\, \bm{\uptheta}_{L+1}]] \nonumber \\
    &\quad=
        \mathbb{E}_{Q^*}[
            \tilde f^2(\mathbf{x}_n) + 2 \tilde b \tilde f(\mathbf{x}_n) + \tilde b^2
            -\mathbb{E}_{P}[\tilde f^2(\mathbf{x}_n) + 2 \tilde b \tilde f(\mathbf{x}_n) + \tilde b^2\,|\, \bm{\uptheta}_{L+1}]
        ] \\
    &\quad=
    \mathbb{E}_{Q^*}[
            \tilde f^2(\mathbf{x}_n)
            -\mathbb{E}_{P}[\tilde f^2(\mathbf{x}_n) \,|\, \bm{\uptheta}_{L+1}]
        ]
    + 2\, \mathbb{E}_{Q^*}[\tilde b (\tilde f(\mathbf{x}_n) - \mathbb{E}_P[\tilde f(\mathbf{x}_n) \,|\, \bm{\uptheta}_{L+1}])].
\end{align}
This gives
\begin{align}
    &\operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}}) \nonumber \\
    &\quad\le \frac1{2\sigma^2}\sum_{n=1}^N\Big(
        \abs{\mathbb{E}_{Q^*}[\tilde f^2(\mathbf{x}_n) -\mathbb{E}_{P}[\tilde f^2(\mathbf{x}_n)\,|\, \bm{\uptheta}_{L+1}]]}
        + 2 \abs{y_n} \abs{\mathbb{E}_{Q^*}[\tilde f(\mathbf{x}_n) -\mathbb{E}_{P}[\tilde f(\mathbf{x}_n)\,|\, \bm{\uptheta}_{L+1}]]} \nonumber \\
    &\hphantom{\quad\le \frac1{2\sigma^2}\sum_{n=1}^N\Big(}\; + 2\, \abs{\mathbb{E}_{Q^*}[\tilde b (\tilde f(\mathbf{x}_n) - \mathbb{E}_P[\tilde f(\mathbf{x}_n) \,|\, \bm{\uptheta}_{L+1}])]} \Big).
\end{align}
By oddness of $\phi$, it can be seen that $\mathbb{E}_P[\tilde f(\mathbf{x}_n) \,|\, \bm{\uptheta}_{L+1}] = 0$.
Therefore,
\begin{align}
    &\operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}}) \nonumber \\
    &\quad\le \frac1{2\sigma^2}\sum_{n=1}^N\Big(
        \abs{\mathbb{E}_{Q^*}[\tilde f^2(\mathbf{x}_n) -\mathbb{E}_{P}[\tilde f^2(\mathbf{x}_n)\,|\, \bm{\uptheta}_{L+1}]]}
        + 2 \abs{y_n} \abs{\mathbb{E}_{Q^*}[\tilde f(\mathbf{x}_n)]} + 2 \abs{\mathbb{E}_{Q^*}[\tilde b \tilde f(\mathbf{x}_n)]} \Big).
\end{align}
Here
\begin{align}
    \mathbb{E}_{Q^*}[\tilde f^2(\mathbf{x}_n) -\mathbb{E}_{P}[\tilde f^2(\mathbf{x}_n)\,|\, \bm{\uptheta}_{L+1}]]
    &= \tfrac1M\operatorname{tr} \mathbb{E}_{Q^*}[\mathbf{w}_{L+1} \mathbf{w}_{L+1}^{\text{\textsf{T}}}] (
        \mathbb{E}_{Q^*}[\phi(\mathbf{z}_L) \phi(\mathbf{z}_L)^{\text{\textsf{T}}}]
        - \mathbb{E}_{P}[\phi(\mathbf{z}_L) \phi(\mathbf{z}_L)^{\text{\textsf{T}}}]
    ), 
\end{align}
which is $O(1/\sqrt{M})$ by \cref{eq:dist:complicated_trace}, and
\begin{align}
    \abs{\mathbb{E}_{Q^*}[\tilde b \tilde f(x_n)]}
    &\le
        \abs{\mathbb{E}_{Q^*}[b_{L+1}]} \abs{\mathbb{E}_{Q^*}[\tilde f(x_n)]}
        + \tfrac1{M}\abs{\mathbb{E}_{Q^*}[\lra{\mathbf{w}_{L+1}, \alpha \mathbf{1}} \lra{\mathbf{w}_{L+1}, \phi(\mathbf{z}_{L})}]},



\end{align}
which is $O(1/\sqrt{M})$ by \cref{eq:dist:bias,eq:dist:mean} applied to the first term and \cref{eq:dist:complicated_inner_prod} applied to the second term. Therefore, $\operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}}) = O(1/\sqrt{M})$.

\textbf{Step 2 (beginning of conclusion of proof).}
Let
\begin{equation}


    d_M = \sum_{n=1}^N (y_n - \mathbb{E}_{Q^*}[b_{L+1}]).
\end{equation}
Although $d_M$ depends on $Q^*_{b_{L+1}}$ which in turn depends on $M$, note that $\mathbb{E}_{Q^*}[b_{L+1}]$ and therefore $d_M$ can be treated like unknown but bounded constants.
Set $c_M = \frac{\alpha d_M}{\alpha^2 N + \sigma^2}$.
We make two claims:
\begin{align}
    \operatorname{KL}(Q^*_{\mathbf{w}_{L+1} - \frac{c_M}{\sqrt{M}} \mathbf{1}}, P_{\mathbf{w}_{L+1}}) &\to 0,
     \tag{Claim 1} \quad \\
    c_M &\to c_\infty \tag{Claim 2}
\end{align}
where $Q^*_{\mathbf{w}_{L+1} - \frac{c_M}{\sqrt{M}} \mathbf{1}}$ is the distribution of $\mathbf{w}_{L+1} - \frac{c_M}{\sqrt{M}} \mathbf{1}$ under $Q^*$ and $c_\infty \in \mathbb{R}$ is some constant.
The claims will be proven in the next parts.
Assuming the claims, denote $\mathbf{w}_{L+1}' = \mathbf{w}_{L+1} - \frac{c_M}{\sqrt{M}}  \mathbf{1}$ and $\phi_\alpha = \phi + \alpha$ and decompose
\begin{align}
    \tfrac{1}{\sqrt{M}}\lra{\mathbf{w}_{L+1}, \phi_\alpha(\mathbf{z}_L)}
    &= \tfrac{1}{\sqrt{M}}\lra{\mathbf{w}'_{L+1}, \phi_\alpha(\mathbf{z}_L)} + \tfrac{c_M}{M} \lra{\mathbf{1}, \phi_\alpha(\mathbf{z}_L)}.
\end{align}
By Chebyshev's inequality, we have $\tfrac{c_M}{M} \lra{\mathbf{1}, \phi(\mathbf{z}_L)} \to 0$ in probability under $Q^*$:
\begin{align}
    \mathbb{E}_{Q^*}[\tfrac{1}{M} \lra{\mathbf{1}, \phi(\mathbf{z}_L)}]
    &\le \tfrac{1}{\sqrt{M}} \norm{\mathbb{E}_{Q^*}[\phi(\mathbf{z}_L)]}_2 \\
    \mathbb{V}_{Q^*}[\tfrac1M\lra{\mathbf{1}, \phi(\mathbf{z}_L)}]
    &= \tfrac1{M^2} \lra{\mathbf{1}, \mathbb{E}_{Q^*}[\phi(\mathbf{z}_L)\phi(\mathbf{z}_L)^{\text{\textsf{T}}}] \mathbf{1}}
    - \tfrac{1}{M^2} \lra{\mathbf{1}, \mathbb{E}_{Q^*}[\phi(\mathbf{z}_L)]}^2 \\
    &\le \tfrac1M \norm{\mathbb{E}_{Q^*}[\phi(\mathbf{z}_L)\phi(\mathbf{z}_L)^{\text{\textsf{T}}}]}_2 + \tfrac1M \norm{\mathbb{E}_{Q^*}[\phi(\mathbf{z}_L)]}_2^2,
\end{align}
which are both $O(1/\sqrt{M})$ using \cref{eq:dist:phi,eq:dist:outer}.
Since $\tfrac{c_M}{M} \lra{\mathbf{1}, \phi(\mathbf{z}_L)} \to 0$ in probability, $\tfrac{c_M}{M} \lra{\mathbf{1}, \phi_\alpha(\mathbf{z}_L)} = \tfrac{c_M}{M} \lra{\mathbf{1}, \phi(\mathbf{z}_L)} + \alpha c_M \to \alpha c_\infty$ in probability by Claim 2.

Suppressing the dependence on $\mathbf{x}$, define $g_{\bm{\uptheta}} = \tfrac{1}{\sqrt{M}}\lra{\mathbf{w}'_{L+1}, \phi_\alpha(\mathbf{z}_L)}$ and note that it is a deterministic function of $(\mathbf{w}'_{L+1}, \bm{\uptheta}_{1:L})$.
Also write $f_{\bm{\uptheta}} = \tfrac{1}{\sqrt{M}}\lra{\mathbf{w}_{L+1}, \phi_\alpha(\mathbf{z}_L)}$ and note that it the \emph{same} deterministic function of $(\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L})$.
(That it is the same deterministic function will allow us to use the data processing inequality below.)
Let $I \in \mathbb{N}$ and $\mathbf{X} = (\mathbf{x}_1, \ldots, \mathbf{x}_I) \in (\mathbb{R}^{D\ss{i}})^I$.
Let $Q^{(M)}_{g}$ be the finite-dimensional distribution of $g$ at $\mathbf{X}$ under the optimal mean-field solution $Q^*$ at width $M$
and
let $P^{(M)}_{f}$ be the finite-dimensional distribution of $f$ at $\mathbf{X}$ under the prior $P$ at width $M$.
Using Pinsker's inequality and the data processing inequality for KL-divergences we have
\begin{align}
    \mathrm{TV}(Q^{(M)}_{g}, P^{(M)}_{f}) \leq \sqrt{\tfrac{1}{2}\operatorname{KL}(Q^{(M)}_{g}, P^{(M)}_{f})} \leq \sqrt{\tfrac{1}{2}\operatorname{KL}(\ensuremath{Q}^{(M)}_{\mathbf{w}'_{L+1}, \bm{\uptheta}_{1:L}},\ensuremath{P}^{(M)}_{\mathbf{w}_{L+1}, \bm{\uptheta}_{1:L}})}, \label{eqn:pinsker0}
\end{align}
which goes to zero as $M \to \infty$ by the previous part and Claim 1.
Let $d$ be the L\'evy--Prokhorov metric on $\mathbb{R}^I$ with the Borel $\sigma$-algebra.
Since $\mathbb{R}^I$ is separable, the L\'evy--Prokhorov metric metrizes weak convergence.
Moreover, since $\mathbb{R}^I$ is separable, the L\'evy--Prokhorov metric is upper bounded by the total variation distance.
By triangle inequality we then bound the distance between $Q^{(M)}_{g}$ and the NNGP, which we denote by $P\ss{NN}$:
\begin{align}
    d(Q^{(M)}_{g}, P\ss{NN})
    \leq
        d(Q^{(M)}_{g}, P^{(M)}_{f})
        + d(P^{(M)}_{f}, P\ss{NN})
    \leq
        \operatorname{TV}(Q^{(M)}_{g}, P^{(M)}_{f})
        + d(P^{(M)}_{f}, P\ss{NN}).
\end{align}
As $M \to \infty$, the first term converges to zero by \cref{eqn:pinsker0} and the second term converges to zero because $P_f^{(M)}$ converges to the NNGP \citep{matthews_2018}.
Hence, $Q^{(M)}_{g}$ converges weakly to the NNGP, $P\ss{NN}$.
Since $f = g + \tfrac{c_M}{M} \lra{\mathbf{1}, \phi_\alpha(\mathbf{z}_L)}$ and we previously showed that $\tfrac{c_M}{M} \lra{\mathbf{1}, \phi_\alpha(\mathbf{z}_L)} \to \alpha c_\infty$ in probability under $Q^*$, we conclude that, along any finite-dimensional distribution, $f$ converges to the NNGP plus the constant $\alpha c_\infty$.
It remains to add the limiting distribution of the bias, which we do in the last step of the proof.

\textbf{Step 3 (proof of Claim 1).}
We previously claimed that
\begin{equation}
    \operatorname{KL}(Q^*_{\mathbf{w}_{L+1} - \frac{c_M}{\sqrt{M}} \mathbf{1}}, P_{\mathbf{w}_{L+1}}) \to 0.
\end{equation}
We now prove this claim.

Let $q^*(\bm{\uptheta}) = q^*(\mathbf{w}_{L+1})q^*(b_{L+1})q^*(\bm{\uptheta}_{1:L})$ be the density of $Q^*$ w.r.t.\ the Lebesgue measure.
Let $\mathcal{L}(q(\mathbf{w}_{L+1}),q(b_{L+1}),q(\bm{\uptheta}_{1:L}))$ be the ELBO:
\begin{align}
    &\mathcal{L}(q(\mathbf{w}_{L+1}),q(b_{L+1}),q(\bm{\uptheta}_{1:L})) \nonumber \\
    &\qquad= \mathbb{E}_q[\log p(\mathbf{y} \,|\, \bm{\uptheta})]
        - \operatorname{KL}(q(\mathbf{w}_{L+1}),p(\mathbf{w}_{L+1}))
        - \operatorname{KL}(q(b_{L+1}),p(b_{L+1}))
        - \operatorname{KL}(q(\bm{\uptheta}_{1:L}),p(\bm{\uptheta}_{1:L})).
\end{align}
Because $Q^*$ is optimal, $q^*(\mathbf{w}_{L+1})$ maximizes the function $q(\mathbf{w}_{L+1}) \mapsto \mathcal{L}(q(\mathbf{w}_{L+1}),q^*(b_{L+1}),q^*(\bm{\uptheta}_{1:L}))$.
We therefore parametrize $q(\mathbf{w}_{L+1}) = \mathcal{N}(\bm{\upmu}, \operatorname{diag}(\bm{\upnu}))$ and set the gradients of $(\bm{\upmu}, \bm{\upnu}) \mapsto \mathcal{L}(q(\mathbf{w}_{L+1}),q^*(b_{L+1}),q^*(\bm{\uptheta}_{1:L}))$ to zero to find equations which characterize the mean and variance of $q^*(\mathbf{w}_{L+1}) = \mathcal{N}(\bm{\upmu}^*, \operatorname{diag}(\bm{\upnu}^*))$.

Consider the joint density $q(\bm{\uptheta}) = q(\mathbf{w}_{L+1})q^*(b_{L+1})q^*(\bm{\uptheta}_{1:L})$.
Denote $\phi_\alpha = \phi + \alpha$.
Compute
\begin{align}
    &\mathbb{E}_q[\log p(\mathbf{y} \,|\, \bm{\uptheta})]
    - \operatorname{KL}(q(\mathbf{w}_{L+1}),p(\mathbf{w}_{L+1})) \nonumber \\
    &\;
    = -\frac1{2\sigma^2}\sum_{n=1}^N
    \parens*{
        \tfrac1M\lra{
            \bm{\upmu} \bm{\upmu}^{\text{\textsf{T}}} + \operatorname{diag}(\bm{\upnu}),
            \mathbb{E}_{Q^*}[\phi_\alpha(\mathbf{z}_L)\phi_\alpha(\mathbf{z}_L)^{\text{\textsf{T}}}]
        }
        - 2 \tfrac{1}{\sqrt{M}}\lra{
                \bm{\upmu},
                \mathbb{E}_{Q^*}[(y_n - b_{L+1})\phi_\alpha(\mathbf{z}_L)]
        }
        + \mathbb{E}_{Q^*}[y_n - b_{L+1}]^2
    } \nonumber\\
    &\quad\qquad - \frac12 \norm{\bm{\upmu}}_2^2 - \frac12 \sum_{m=1}^M(\nu_m - 1 - \log(\nu_m)).
\end{align}
Denote
\begin{equation}
    \mathbf{A} = \frac1M \sum_{n=1}^N \mathbb{E}_{Q^*}[\phi_\alpha(\mathbf{z}_L(\mathbf{x}_n))\phi_\alpha(\mathbf{z}_L(\mathbf{x}_n))^{\text{\textsf{T}}}],
    \quad
    \mathbf{b} = \frac1{\sqrt{M}}\sum_{n=1}^N(y_n - \mathbb{E}_q[b_{L+1}]) \mathbb{E}_{Q^*}[\phi_\alpha(\mathbf{z}_L(\mathbf{x}_n))].
\end{equation}
Then the part of the ELBO depending on $\bm{\upmu}$ and $\bm{\upnu}$ can be written as
\begin{equation}
     -\frac1{2\sigma^2}
    \sbrac*{
        \lra{
            \bm{\upmu} \bm{\upmu}^{\text{\textsf{T}}} + \operatorname{diag}(\bm{\upnu}),
            \mathbf{A}
        }
        - 2 \lra{
                \bm{\upmu},
                \mathbf{b}
        }
        + (y_n - \mathbb{E}_{Q^*}[b_{L+1}])^2
    }  - \frac12 \norm{\bm{\upmu}}_2^2 - \frac12 \sum_{m=1}^M(\nu_m - 1 - \log(\nu_m)).
\end{equation}
Setting the gradient with respect to $\bm{\upmu}$ to zero gives
\begin{equation}
    -\frac1{\sigma^2}\mathbf{A} \bm{\upmu}^* + \frac1{\sigma^2}\mathbf{b} - \bm{\upmu}^* = 0
    \implies
    \bm{\upmu}^* = (\mathbf{A} + \sigma^2 \mathbf{I})^{-1}\mathbf{b}.
\end{equation}
Similarly, setting the gradient with respect $\nu_m$ to zero gives
\begin{equation}
    -\frac{1}{2\sigma^2} A_{mm} - \frac12 + \frac12\frac1{\nu_m^*} = 0
    \implies
    \nu_m^* = \frac{1}{1 + \frac{1}{\sigma^2}A_{mm}}.
\end{equation}
Therefore,
\begin{align}
    \operatorname{KL}(Q^*_{\mathbf{w}_{L+1} - \tfrac{c_M}{\sqrt{M}} \mathbf{1}}, P_{\mathbf{w}_{L+1}})
    &= \frac12 \norm{\bm{\upmu}^* - \tfrac{c_M}{\sqrt{M}} \mathbf{1}}_2^2
    + \frac12\sum_{m=1}^M (\nu_m^* - 1 - \log(\nu_m^*)) \\
    &= \frac{1}{2 \sigma^2} \norm{\bm{\upmu}^* - \tfrac{c_M}{\sqrt{M}} \mathbf{1}}_2^2
    + \frac{1}{2} \sum_{m=1}^M\parens*{
        \log(1 + \tfrac{1}{\sigma^2}A_{mm})
        - \frac{\tfrac{1}{\sigma^2}A_{mm}}{1 + \tfrac{1}{\sigma^2}A_{mm}}
    } \\
    &\overset{\text{(i)}}{\le} \frac{1}{2 \sigma^2} \norm{\bm{\upmu}^* - \tfrac{c_M}{\sqrt{M}} \mathbf{1}}_2^2
    + \frac{1}{2} M\parens*{
        \log(1 + \tfrac1{M}\tfrac{M}{\sigma^2}A_{m^*})
        - \frac{\tfrac1{M}\tfrac{M}{\sigma^2}A_{m^*}}{1 + \tfrac1{M}\tfrac{M}{\sigma^2}A_{m^*}}
    } \\
    &\overset{\text{(ii)}}{\le} \frac{1}{2 \sigma^2} \norm{\bm{\upmu}^* - \tfrac{c_M}{\sqrt{M}} \mathbf{1}}_2^2
    + \frac{1}{2 \sigma^2} \frac{M}{\sigma^2}A^2_{m^*}
\end{align}
where in (i) $A_{m^*} = \relax_{m \in [M]} A_{mm}$ and we use that $a - 1 - \log(a)$ is increasing in $a$ for $a<1$ and that $\nu^*_m<1$. In (ii) we used the inequality\footnote{
    Note that the inequality is equivalent to
    $
        \log(1 + x) - \frac{x}{1 + x} \le x^2
    $
    for all $x > 0$, which follows from $\log(1 + x) < x$ for all $x > 0$.
}
\begin{equation}
    x \parens*{\log(1 + \tfrac{c}{x}) - \frac{\tfrac{c}{x}}{1+\tfrac{c}{x}}} \le \frac{c^2}{x}
    \quad 
    \text{for all $c \ge 0$ and $x > 0$}
\end{equation}
with $c = \tfrac{M}{\sigma^2}A_{m^*} \ge 0$ and $x = M > 0$.
By \cref{eq:dist:square}, $M A^2_{m^*} = O(1/M)$, so the claim is shown if
\begin{equation}
    \norm{(\mathbf{A} + \sigma^2 \mathbf{I})^{-1} \mathbf{b} - \tfrac{c_M}{\sqrt{M}} \mathbf{1}}_2 \to 0.
\end{equation}
Using that
\begin{equation}
    \norm{(\mathbf{A} + \sigma^2 \mathbf{I})^{-1} \mathbf{b} - \tfrac{c_M}{\sqrt{M}} \mathbf{1}}_2
    \le \norm{(\mathbf{A} + \sigma^2 \mathbf{I})^{-1}}_2 \norm{\mathbf{b} - \tfrac{c_M}{\sqrt{M}} (\mathbf{A} + \sigma^2 \mathbf{I})\mathbf{1}}_2
    \le \sigma^{-2} \norm{\mathbf{b} - \tfrac{c_M}{\sqrt{M}} (\mathbf{A} + \sigma^2 \mathbf{I})\mathbf{1}}_2,
\end{equation}
it suffices to show that
$\sqrt{M}\norm{\mathbf{b} - \tfrac{c_M}{\sqrt{M}} (\mathbf{A} + \sigma^2 \mathbf{I})\mathbf{1}}_\infty \to 0$:
\begin{align}
    &\relax_{m \in [M]} \Bigg| \sum_{n=1}^N(y_n - \mathbb{E}_q[b_{L+1}])\mathbb{E}_{Q^*}[\phi_\alpha(z_{L,m}(\mathbf{x}_n))] \\
    &\qquad\qquad- \frac{\alpha d_M}{\alpha^2 N + \sigma^2}
    \parens*{\sigma^2 +\frac1M\sum_{m'=1}^M \sum_{n=1}^N \mathbb{E}_{Q^*}[\phi_\alpha(z_{L,m}(\mathbf{x}_n))\phi_\alpha(z_{L,m'}(\mathbf{x}_n))]}\Bigg| \to 0. \nonumber
\end{align}
Expand
\begin{align}
    &\frac1M\sum_{m'=1}^M \sum_{n=1}^N \mathbb{E}_{Q^*}[\phi_\alpha(z_{L,m}(\mathbf{x}_n))\phi_\alpha(z_{L,m'}(\mathbf{x}_n))] \nonumber \\
    &\quad= 
        \frac1M\sum_{m'=1}^M \sum_{n=1}^N
        (
            \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n)) \phi(z_{L,m'}(\mathbf{x}_n))]
            + \alpha( \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n))] + \mathbb{E}_{Q^*}[\phi(z_{L,m'}(\mathbf{x}_n))]) + \alpha^2
        ) \\
    &\quad= 
        \frac1M\sum_{n=1}^N
            \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n))^2]
             + \frac1M\sum_{m'=1}^M \sum_{n=1}^N \alpha^2
         \\
    &\quad\qquad
    + \frac1M\sum_{m'\neq m}^M \sum_{n=1}^N
            \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n)) \phi(z_{L,m'}(\mathbf{x}_n))]
    +\frac1M\sum_{m'=1}^M \sum_{n=1}^N
        \alpha( \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n))] + \mathbb{E}_{Q^*}[\phi(z_{L,m'}(\mathbf{x}_n))]). \nonumber
\end{align}
Collecting the first two terms of the expansion, note that, by definition of $d_M$ and \cref{eq:dist:square},
\begin{equation}
    \relax_{m \in [M]} \Bigg|\sum_{n=1}^N (y_n - \mathbb{E}_{Q^*}[b_{L+1}]) \alpha
    - \frac{\alpha d_M}{\alpha^2 N + \sigma^2}
    \parens*{\sigma^2
        +\frac1M \sum_{n=1}^N \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n))^2] + \frac1M \sum_{n=1}^N \sum_{m'=1}^M \alpha^2
    }\Bigg|
    \to 0.
\end{equation}
It therefore remains to show that the remainder also goes, which follows from the following three limits:
\begin{align}
    \relax_{m \in [M]}\,\Bigg|\sum_{n=1}^N (y_n - \mathbb{E}_{Q^*}[b_{L+1}]) \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n))]\Bigg| \overset{\text{\cref{eq:dist:phi,eq:dist:bias} with } \operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}}) \to 0}&{\to} 0, \\
    \relax_{m \in [M]}\,\Bigg|\frac1M \sum_{n=1}^N \sum_{m' \neq m}^M \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n))\phi(z_{L,m'}(\mathbf{x}_n))]\Bigg| \overset{\text{\cref{eq:dist:cov} with } \operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}}) \to 0}&{\to} 0, \\
    \relax_{m \in [M]}\,\Bigg|\frac{\alpha}M \sum_{n=1}^N \sum_{m'=1}^M \mathbb{E}_{Q^*}[\phi(z_{L,m}(\mathbf{x}_n)) + \phi(z_{L,m'}(\mathbf{x}_n))]\Bigg| \overset{\text{\cref{eq:dist:phi} with } \operatorname{KL}(Q^*_{\bm{\uptheta}_{1:L}}, P_{\bm{\uptheta}_{1:L}}) \to 0}&{\to} 0.
\end{align}

\textbf{Step 4 (convergence of the bias).}
The starting point is to note that
\begin{align}
    &\tfrac{1}{\sqrt{M}}
    \mathbb{E}_{Q^*}[\lra{\mathbf{w}_{L+1}, \phi_\alpha(\mathbf{z}_{L})}] \nonumber \\
    &\quad=
        \tfrac{1}{\sqrt{M}}
        \lra{\mathbb{E}_{Q^*}[\mathbf{w}_{L+1} - \tfrac{c_M}{\sqrt{M}} \mathbf{1}],\mathbb{E}_{Q^*}[\phi_\alpha(\mathbf{z}_{L})]}
        +
        \tfrac{c_M}{M}
        \lra{\mathbf{1},\mathbb{E}_{Q^*}[\phi(\mathbf{z}_{L})]}
        + \alpha c_M
\end{align}
where
\begin{equation}
    \alpha c_M
    = \frac{\alpha^2 d_M}{\alpha^2 N + \sigma^2}
    = \frac{\alpha^2}{\alpha^2 N + \sigma^2} \sum_{n=1}^N (y_n - \mathbb{E}_{Q^*}[b_{L+1}])
    \eqqcolon
    \beta ( \overline{y} - \mathbb{E}_{Q^*}[b_{L+1}])
\end{equation}
with
\begin{equation}
    \overline{y} = \frac1N\sum_{n=1}^N y_n,
    \qquad
    \beta = \frac{\alpha^2}{\alpha^2 + \sigma^2 / N}.
\end{equation}
Moreover,
\begin{align*}
    \abs{
        \tfrac{1}{\sqrt{M}}
        \lra{\mathbb{E}_{Q^*}[\mathbf{w}_{L+1} - \tfrac{c_M}{\sqrt{M}} \mathbf{1}],\mathbb{E}_{Q^*}[\phi_\alpha(\mathbf{z}_{L})]}
    }
    &\le \tfrac{1}{\sqrt{M}} (2\operatorname{KL}(Q^*_{\mathbf{w}_{L+1} - \frac{c_M}{\sqrt{M}} \mathbf{1}}, P_{\mathbf{w}_{L+1}}))^{1/2} \norm{\mathbb{E}_{Q^*}[\phi_\alpha(\mathbf{z}_{L})]}_2 \\
    &\le \tfrac{1}{\sqrt{M}} (2\operatorname{KL}(Q^*_{\mathbf{w}_{L+1} - \frac{c_M}{\sqrt{M}}\mathbf{1}}, P_{\mathbf{w}_{L+1}}))^{1/2} (\sqrt{M} \abs{\alpha} + \norm{\mathbb{E}_{Q^*}[\phi(\mathbf{z}_{L})]}_2),
\end{align*}
which is $o(1)$ by the Claim 1 and \cref{eq:dist:phi}; and
\begin{align*}
    \abs{
        \tfrac{c_M}{M}
        \lra{\mathbf{1},\mathbb{E}_{Q^*}[\phi(\mathbf{z}_{L})]}
    }
    &\le \tfrac{c_M}{\sqrt{M}} \norm{\mathbb{E}_{Q^*}[\phi(\mathbf{z}_{L})]}_2,
\end{align*}
which is also $o(1)$ by \cref{eq:dist:phi}.
We conclude that 
\begin{equation}
    \tfrac{1}{\sqrt{M}}
    \mathbb{E}_{Q^*}[\lra{\mathbf{w}_{L+1}, \phi_\alpha(\mathbf{z}_{L})}]
    = \beta ( \overline{y} - \mathbb{E}_{Q^*}[b_{L+1}]) + o(1).
\end{equation}

We proceed like in the second part:
Because $Q^*$ is optimal, $q^*(b_{L+1})$ maximizes the function $q(b_{L+1}) \mapsto \mathcal{L}(q^*(\mathbf{w}_{L+1}),q(b_{L+1}),q^*(\bm{\uptheta}_{1:L}))$.
We therefore parametrize $q(b_{L+1}) = \mathcal{N}(\mu_M, \nu_M)$ and set the gradients of $(\mu_M, \nu_M) \mapsto \mathcal{L}(q(\mathbf{w}^*_{L+1}),q(b_{L+1}),q^*(\bm{\uptheta}_{1:L}))$ to zero to find equations which characterize the mean and variance of $q^*(b_{L+1}) = \mathcal{N}(\mu_M^*, \nu_M^*)$.

Consider the joint density $q(\bm{\uptheta}) = q^*(\mathbf{w}_{L+1})q(b_{L+1})q^*(\bm{\uptheta}_{1:L})$.
Denote $\phi_\alpha = \phi + \alpha$.
Compute
\begin{align}
    &\mathbb{E}_q[\log p(\mathbf{y} \,|\, \bm{\uptheta})]
    - \operatorname{KL}(q(b_{L+1}),p(b_{L+1})) \nonumber \\
    &\quad
    = -\frac1{2\sigma^2}\sum_{n=1}^N
    \parens*{
        \nu_M + \mu_M^2




        - 2 \mu_M (
            y_n
            - \tfrac{1}{\sqrt{M}}\mathbb{E}_{Q^*}[\lra{
                \mathbf{w}_{L+1},
                \phi_\alpha(\mathbf{z}_L)
            }]
        )
        + \mathbb{E}_{Q^*}[(
            y_n
            - \tfrac{1}{\sqrt{M}}\lra{
                \mathbf{w}_{L+1},
                \phi_\alpha(\mathbf{z}_L)
            }
        )^2]
    } \nonumber\\
    &\quad\qquad - \frac12\mu_M^2 - \frac12(\nu_M - 1 - \log(\nu_M)) \\
    &\quad
    = -\frac1{2\sigma^2}\sum_{n=1}^N
    \sbrac*{
        \nu_M + \mu_M^2




        - 2 \mu_M (
            y_n
            - \beta ( \overline{y} - \mu^*_M) + o(1)
        )
        + \mathbb{E}_{Q^*}[(
            y_n
            - \tfrac{1}{\sqrt{M}}\lra{
                \mathbf{w}_{L+1},
                \phi_\alpha(\mathbf{z}_L)
            }
        )^2]
    } \nonumber\\
    &\quad\qquad - \frac12\mu_M^2 - \frac12(\nu_M - 1 - \log(\nu_M)).
\end{align}
Setting the derivative w.r.t.\ $\nu_M$ to zero and solving gives $\nu_M^* = \sigma^2/(\sigma^2 + N)$.
Setting the derivative w.r.t.\ $\mu_M$ to zero, we find
\begin{align}
    0 &= -\frac1{2\sigma^2}\sum_{n=1}^N
    \sbrac*{
        2\mu_M^*




        - 2 (
            y_n
            - \beta ( \overline{y} - \mu_M^*)+o(1)
        )





    } - \mu_M^*\\
    &= -\frac N{2\sigma^2}
    \sbrac*{
        2\mu_M^*




        - 2 (
            y_n
            - \beta ( \overline{y} - \mu_M^*)
        )





    } - \mu_M^*  + o(1)\\
    &= -\frac N{\sigma^2}
    \sbrac*{
        \mu_M^*




        - (
            \overline{y}
            - \beta ( \overline{y} - \mu_M^*)
        )





    } - \mu_M^* + o(1) \\
    &= -\frac N{\sigma^2}
    \sbrac*{
        (1 - \beta) \mu_M^*




        - (1 - \beta) \overline{y}
    } - \mu_M^* + o(1)\\
    &= - (1 - \beta) \frac N{\sigma^2}
    \sbrac*{
        \mu_M^*




        - \overline{y}
    } - \mu_M^* + o(1) \\
    &= - \frac{1}{\alpha^2 + \frac{\sigma^2}{N}}
    \sbrac*{
        \mu_M^*




        - \overline{y}
    } - \mu_M^* + o(1) \\
    \implies
    \mu_M^* &= \frac{1}{(\alpha^2 + \frac{\sigma^2}{M})^{-1} + 1}\parens*{
        \frac{1}{\alpha^2 + \frac{\sigma^2}{M}} \overline{y}
        + o(1)
    }.





























































\end{align}
Therefore, taking $M \to \infty$, under $Q^*$,
\begin{equation}
    b_{L+1} \oto{\text{d}} \mathcal{N}\parens*{\frac{1}{1 + \alpha^2 + \frac{\sigma^2}{N}} \overline{y}, \frac{\sigma^2}{\sigma^2 + N}}.
\end{equation}

\textbf{Step 5 (proof of Claim 2).}
By the previous step, we have that
\begin{align}
    \alpha c_M
    &= \beta (\overline{y} - \mu^*_M) \\
    &\to \beta \parens*{1 - \frac{1}{1 + \alpha^2 + \frac{\sigma^2}{N}}} \overline{y} \\
    &= c_\infty,
\end{align}
which proves Claim 2.

\textbf{Step 6 (end of conclusion of proof).}
In Step 2, we showed that, under $Q^*$, along any finite-dimensional distribution, $\tfrac{1}{M}\lra{\mathbf{w}_{L+1}, \phi_\alpha(\mathbf{z}_L)}$ converges to the NNGP plus the constant $\alpha c_\infty$.
We now add the limiting distribution of the final bias to this, which concludes the proof.
For this, we note that $\alpha c_\infty$ simply adds to the mean of the bias:
\begin{equation}
    \alpha c_M + \mu^*_M \to \parens*{\beta \times 1 + (1 - \beta) \times \frac{1}{1 + \alpha^2 + \frac{\sigma^2}{N}}} \overline{y},

\end{equation}
which agrees with the theorem statement.

