        \tfrac1{M}\abs{\mathbb{E}[\lra{\mathbf{w}_{L+1}, \alpha \mathbf{1}} \lra{\mathbf{w}_{L+1}, \phi(\mathbf{z}_L)}]}
        \overset{\text{(\cref{lem:inner_prod})}}&{\lesssim}
