\end{align}
where $c' = c\sqrt{2\pi}$. Define $u = az$, $b = 1/(2a^2)$ and $I'= \left(\frac{1}{2t^2}, \frac{1}{2s^2}\right)$. Then we can rewrite \cref{eqn:constant-expectation} as 
\begin{align}
    \int \phi(u) e^{-bu^2} du = c' \quad \forall b \in I'.
\end{align}
We have $|u^{2n}\phi(u)e^{-bu^2}|\leq u^{2n}|\phi(u)|e^{-bu^2} \leq   u^{2n}|\phi(u)|e^{-\frac{u^2}{2t^2}}$, which is integrable since $\phi(u)=O(|x|+1)$. Hence we may take $n$ derivatives and apply Leibniz's rule,
\begin{align}\label{eqn:orthogonal-even}
    \frac{\partial^n}{\partial^n b} \int \phi(u) e^{-bu^2} du =  \int u^{2n} \phi(u) e^{-bu^2} du = 0 \quad \forall b \in I', \forall n \in \mathbb{N}.
\end{align}
For a (arbitrary) $b \in I'$, define $w(u) = e^{-bu^2}$ and $L^2(\mathbb{R}, w)$ to be the Hilbert space with inner product $\langle f,g \rangle = \int f(u)g(u)w(u)du$. 
Following 
\citet{126471}, we note that the set of compactly supported functions is dense in $L^2(\mathbb{R}, w)$, and by the Weirstrauss theorem the set of polynomial is dense in the set of compact functions. As a dense subset of a dense set is again dense, we conclude the set of polynomial is dense in $L^2(\mathbb{R}, w)$. 

Writing $\phi(u) = \phi_e(u) + \phi_o(u)$, we have,
\begin{align}
    \int_{-\infty}^\infty u^{2i-1} \phi_e(u) w(u) du &= 0 \quad \forall i \in \mathbb{N}
\end{align}
as the integrand is odd and we integrate over a symmetric domain. Also,
\begin{align}
    \int u^{2n} \frac{\phi(u)+ \phi(-u)}{2}w(u) du &=
    \frac{1}{2}\int u^{2i} \phi(u)w(u) du + \frac{1}{2}\int u^{2n} \phi(-u)w(u) du \\
    &=\frac{1}{2}\int u^{2i} \phi(u)w(u) du + \frac{1}{2}\int u^{2n} \phi(u)w(u) du \\
    &=0 + 0, \quad \forall i \in \mathbb{N},
\end{align}
by \cref{eqn:orthogonal-even}. Since the polynomial are a basis, we have $\phi_e(u) = \sum_{i=0}^\infty \alpha_i u^i$ for some $(\alpha_i)_{i=1}^\infty$. Taking the inner product of both sides with respect to $u^i$, shows that $\alpha_i=0$ for all $i >0$, hence  $\phi_e(u)= c^{\prime\prime}$ for some $c^{\prime\prime} \in \mathbb{R}$, with equality in $L^2(\mathbb{R},w)$. But as $\phi_e$ is continuous, this implies it is equal to a $c^{\prime\prime}$ everywhere.

As $I$ contains an open set, it contains a ball. As $\alpha$ is continuous (\cref{prop:e-is-continuous}) the image of this ball under $\alpha$ is connected i.e.~an interval. As the interval contains at least two points, it contains an open interval.

